import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import {
  canonical, DeliverError, internalDirectory, readRun, remoteProviderAttemptIdentity,
  remoteProviderAttemptObservation, sha256,
  validateRemotePublicationRecord, validateTaskPacket,
} from './state.mjs';
import {
  applyIntegrationCorrectionJournal,
  assertCurrentBinding,
  buildIntegrationCorrectionPublication,
  integrationCorrectionJournalConflicts,
  readIntegrationCorrectionJournal,
  removeIntegrationCorrectionJournal,
  validateIntegrationCorrectionJournal,
  writeIntegrationCorrectionJournal,
} from './current-pm.mjs';
import { inspectProjectState, readPlanPolicy } from './project-state.mjs';
import { parseReviewReceipt } from './review.mjs';
import { parseVerificationResults, renderVerificationArtifacts } from './reporting.mjs';
import { parseStory, readStory, replaceStoryExecution } from './story.mjs';
import { environmentHandle } from './gates.mjs';
import { captureGitAnchor, snapshot } from './scope.mjs';
import { createGitHubRemoteAdapter } from './remote.mjs';

const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const HASH = /^[0-9a-f]{64}$/;
const RUN_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const ACTOR_ID = /^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/;
const MAX_RECORD_BYTES = 8 * 1024 * 1024;
const NO_MUTATION = Symbol('no-mutation');
const PROCESS_INSTANCE = randomUUID();
const ACTIVE_PROVIDER_INVOCATIONS = new Set();
const ENDED_PROVIDER_INVOCATIONS = new Set();
const fail = (message, code = 66) => { throw new DeliverError(message, code); };
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const now = () => new Date().toISOString();
const stamp = () => now().replace('T', ' ').replace('Z', '').slice(0, 16);
const covers = (scope, rel) => scope === rel || rel.startsWith(`${scope}/`);

function git(root, args, { buffer = false, env = undefined } = {}) {
  try {
    return execFileSync('git', ['-C', root, ...args], {
      encoding: buffer ? undefined : 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 30000,
      windowsHide: true, ...(env ? { env: { ...process.env, ...env } } : {}),
    });
  } catch (error) {
    fail(`Git cannot complete local integration: ${String(error.stderr || error.message).trim()}`);
  }
}

function rootPath(root) {
  try {
    const real = fs.realpathSync.native(root);
    const stat = fs.lstatSync(real);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('integration root must be a real directory');
    return real;
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot access integration root: ${error.message}`);
  }
}

function commonRepository(root) {
  const value = String(git(root, ['rev-parse', '--git-common-dir'])).trim();
  return fs.realpathSync.native(path.resolve(root, value));
}

function branch(root) {
  const value = String(git(root, ['symbolic-ref', '--short', 'HEAD'])).trim();
  if (!value) fail('integration checkout must use a named branch');
  return value;
}

function head(root) { return String(git(root, ['rev-parse', '--verify', 'HEAD'])).trim(); }
function tree(root, commit = 'HEAD') { return String(git(root, ['rev-parse', `${commit}^{tree}`])).trim(); }

function statusPaths(root) {
  const records = String(git(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all'])).split('\0').filter(Boolean);
  const paths = [];
  for (let index = 0; index < records.length; index++) {
    const item = records[index];
    if (item.length < 4) continue;
    const status = item.slice(0, 2);
    paths.push(item.slice(3));
    if ((status[0] === 'R' || status[0] === 'C') && records[index + 1]) paths.push(records[++index]);
  }
  return paths.filter((rel) => rel !== '.deliver' && !rel.startsWith('.deliver/'));
}

function assertClean(root) {
  const dirty = statusPaths(root);
  if (dirty.length) fail(`integration checkout has uncommitted project paths: ${dirty.sort().join(', ')}`);
  const indexTree = String(git(root, ['write-tree'])).trim();
  if (indexTree !== tree(root)) fail('integration checkout index differs from HEAD');
}

function assertOrdinaryIndex(root) {
  const rows = git(root, ['ls-files', '-v', '-z'], { buffer: true }).toString('utf8').split('\0').filter(Boolean);
  const hidden = rows.filter((row) => row[0] !== 'H').map((row) => row.slice(2));
  if (hidden.length) fail(`integration checkout has unsupported index flags: ${hidden.sort().join(', ')}`);
}

function protectedShape(anchor, root = true) {
  return {
    metadata_version: anchor.metadata_version,
    ...(root ? { ref: anchor.ref } : {}),
    protected_hash: anchor.protected_hash,
    submodules: Object.fromEntries(Object.entries(anchor.submodules || {})
      .map(([rel, nested]) => [rel, protectedShape(nested, false)])),
  };
}

const protectedIgnored = (rel) => /(^|\/)(?:AGENTS|CLAUDE)\.md$/.test(rel)
  || /(^|\/)\.(?:agents|codex)(?:\/|$)/.test(rel)
  || rel.endsWith('.sdd') || /(^|\/)\.specdd(?:\/|$)/.test(rel)
  || /(^|\/)(?:config|configs|contract|contracts)(?:[./]|$)/.test(rel);

function identified(body) {
  return { ...body, identity: sha256(canonical(body)) };
}

function emptyProviderSlot() {
  return { version: 'remote-provider-slot-v1', active_token: null, attempts: [], effect: null };
}

function newRemoteEnvelope() {
  return {
    version: 'remote-publication-v1',
    source: {
      status: 'empty', remote: null, repository: null,
      publication: emptyProviderSlot(), merge: emptyProviderSlot(), proof: null,
    },
    integration_evidence: null,
    closure: null,
    handoff_repair: { publication_retry: 0, attempts: [], proof: null },
    completion: null,
  };
}

function remoteEnvelope(record) {
  record.remote ||= newRemoteEnvelope();
  return record.remote;
}

function remoteSlot(record, area, operation, repairToken = null) {
  const remote = remoteEnvelope(record);
  if (area === 'source') return remote.source[operation];
  if (area === 'closure') return remote.closure?.publication?.[operation];
  if (area === 'repair') {
    const attempt = repairToken
      ? remote.handoff_repair.attempts.find((item) => item.token === repairToken)
      : remote.handoff_repair.attempts.at(-1);
    return attempt?.publication?.[operation];
  }
  fail('remote provider operation slot is unavailable');
}

function lastTransition(attempt) { return attempt.transitions.at(-1); }

function refreshAttempt(attempt) {
  attempt.identity = remoteProviderAttemptIdentity(attempt);
  return attempt;
}

function appendAttemptTransition(attempt, body) {
  const transition = identified({ ...body, previous: lastTransition(attempt)?.identity || null });
  attempt.transitions.push(transition);
  return refreshAttempt(attempt);
}

function providerResult(value, expectedHead) {
  let bytes;
  try { bytes = Buffer.byteLength(JSON.stringify(value)); } catch { fail('provider result is not serializable'); }
  if (!value || typeof value !== 'object' || Array.isArray(value) || bytes > 2 * 1024 * 1024
    || typeof value.state !== 'string' || value.expectedHead !== expectedHead) fail('provider returned an invalid or unbound result');
  return structuredClone(value);
}

function domainProviderState(operation, state) {
  if (state === 'PUBLISHED') return 'PUBLISHED';
  if (state === 'READY') return 'READY';
  if (state === 'MERGED') return operation.includes('source') ? 'SOURCE_MERGED' : 'MERGED';
  if (state === 'MERGED_BASE_ADVANCED') return operation.includes('source') ? 'SOURCE_BASE_ADVANCED' : 'HANDOFF_BASE_RACE';
  if (['PR_DRAFT', 'CHECKS_PENDING', 'MERGE_PENDING'].includes(state)) return 'PENDING';
  if (['PUSH_REJECTED', 'PR_WRITE_FAILED', 'PR_READY_FAILED', 'CHECKS_FAILED', 'MERGE_REJECTED'].includes(state)) return 'FAILED';
  return 'UNKNOWN';
}

function remoteResult(operation, state, extra = {}) {
  return { operation, state, ...extra };
}

function safeRemoteInput(value, label, max, { multiline = false } = {}) {
  if (typeof value !== 'string' || Buffer.byteLength(value) > max || value.includes('\0')
    || (!multiline && (!value.trim() || /[\x00-\x1f\x7f]/.test(value)))) fail(`invalid remote ${label}`, 64);
  return value;
}

function sourceTarget(record, remote = undefined) {
  const envelope = record.remote;
  const selected = remote ?? envelope?.source?.remote ?? 'origin';
  if (envelope?.source?.remote && selected !== envelope.source.remote) fail('remote differs from the retained source publication');
  return {
    root: record.source.root, remote: selected, storyBranch: record.source.branch,
    integrationBranch: record.destination.branch, expectedHead: record.source.candidate,
  };
}

function providerAttemptResult(wrapper, operation, attempt, providerValue) {
  return {
    file: wrapper.file, record: wrapper.record, hash: wrapper.hash,
    result: remoteResult(operation, domainProviderState(operation, providerValue.state), {
      attempt_token: attempt.token, provider_state: providerValue.state,
      ...(providerValue.pr ? { pr: providerValue.pr } : {}),
      ...(providerValue.mergeCommit ? { merge_commit: providerValue.mergeCommit } : {}),
      ...(providerValue.remoteBase ? { remote_base: providerValue.remoteBase } : {}),
    }),
  };
}

function executeProviderAttempt(recordArg, expectedRecordHash, {
  area, slotName, operation, input, expectedHead, invoke, successStates = [], retry = 0, repairToken = null,
}, cwd) {
  const inputIdentity = sha256(canonical(input));
  const prepared = withRecord(recordArg, expectedRecordHash, (record) => {
    const slot = remoteSlot(record, area, slotName, repairToken);
    const previous = slot.attempts.at(-1);
    if (!slot.active_token && slot.effect && previous && lastTransition(previous)?.state === 'observed') {
      const stripObservation = ({ remote_observation: _observation, ...rest }) => rest;
      if (canonical(stripObservation(previous.input)) !== canonical(stripObservation(input))) {
        fail('remote provider input differs from the retained successful intent');
      }
      const retained = lastTransition(previous).result;
      return { [NO_MUTATION]: true, value: remoteResult(operation, domainProviderState(operation, retained.state), {
        attempt_token: previous.token, provider_state: retained.state,
        ...(retained.pr ? { pr: retained.pr } : {}), ...(retained.mergeCommit ? { merge_commit: retained.mergeCommit } : {}),
        ...(retained.remoteBase ? { remote_base: retained.remoteBase } : {}),
      }) };
    }
    if (!slot.active_token && previous && previous.input_identity === inputIdentity
      && lastTransition(previous)?.state === 'observed') {
      const retained = lastTransition(previous).result;
      return { [NO_MUTATION]: true, value: remoteResult(operation, domainProviderState(operation, retained.state), {
        attempt_token: previous.token, provider_state: retained.state,
        ...(retained.pr ? { pr: retained.pr } : {}),
        ...(retained.mergeCommit ? { merge_commit: retained.mergeCommit } : {}),
        ...(retained.remoteBase ? { remote_base: retained.remoteBase } : {}),
      }) };
    }
    if (!slot.active_token && previous && lastTransition(previous)?.state === 'observed'
      && previous.input_identity !== inputIdentity) {
      fail('remote provider input differs from the retained unresolved or terminal attempt');
    }
    const active = slot.active_token && slot.attempts.find((item) => item.token === slot.active_token);
    if (active) {
      const transition = lastTransition(active);
      if (active.input_identity !== inputIdentity) fail('active remote provider attempt has different immutable input');
      if (transition.state === 'executing') return { [NO_MUTATION]: true,
        value: remoteResult(operation, 'PROVIDER_EXECUTING', { attempt_token: active.token }) };
      if (transition.state === 'prepared') return { attempt: active, resumed: true };
    }
    const token = randomUUID();
    const attempt = {
      version: 'remote-provider-attempt-v1', token, operation, ordinal: slot.attempts.length,
      input: structuredClone(input), input_identity: inputIdentity, predecessor_record_hash: expectedRecordHash,
      retry, supersedes: null, transitions: [], disposition: 'active', superseded_by: null, identity: null,
    };
    appendAttemptTransition(attempt, { state: 'prepared', at: now() });
    slot.attempts.push(attempt);
    slot.active_token = token;
    return { attempt, resumed: false };
  }, cwd);
  if (prepared.unchanged) return prepared;
  const preparedAttempt = remoteSlot(prepared.record, area, slotName, repairToken).attempts
    .find((item) => item.token === prepared.result.attempt.token);
  const invocationToken = randomUUID();
  const executing = withRecord(prepared.file, prepared.hash, (record) => {
    const slot = remoteSlot(record, area, slotName, repairToken);
    const attempt = slot.attempts.find((item) => item.token === preparedAttempt.token);
    if (!attempt || slot.active_token !== attempt.token || lastTransition(attempt).state !== 'prepared') {
      fail('remote provider attempt is no longer prepared');
    }
    appendAttemptTransition(attempt, {
      state: 'executing', at: now(), invocation: {
        token: invocationToken, pid: process.pid, process_instance: PROCESS_INSTANCE,
        operation, input_identity: attempt.input_identity,
      },
    });
    return { attempt_token: attempt.token, invocation_token: invocationToken };
  }, cwd);
  let raw;
  ACTIVE_PROVIDER_INVOCATIONS.add(invocationToken);
  try { raw = invoke(); }
  catch {
    ENDED_PROVIDER_INVOCATIONS.add(invocationToken);
    return { file: executing.file, record: executing.record, hash: executing.hash,
      result: remoteResult(operation, 'PROVIDER_UNKNOWN', { attempt_token: preparedAttempt.token }) };
  } finally { ACTIVE_PROVIDER_INVOCATIONS.delete(invocationToken); }
  ENDED_PROVIDER_INVOCATIONS.add(invocationToken);
  const value = providerResult(raw, expectedHead);
  const observed = withRecord(executing.file, executing.hash, (record) => {
    const slot = remoteSlot(record, area, slotName, repairToken);
    const attempt = slot.attempts.find((item) => item.token === preparedAttempt.token);
    if (!attempt || lastTransition(attempt).invocation?.token !== invocationToken) fail('remote provider invocation identity changed');
    appendAttemptTransition(attempt, {
      state: 'observed', at: now(), invocation_token: invocationToken,
      result: value, result_identity: sha256(canonical(value)),
    });
    slot.active_token = null;
    if (successStates.includes(value.state)) {
      attempt.disposition = 'proven';
      refreshAttempt(attempt);
      slot.effect = identified({ attempt_identity: attempt.identity,
        result_identity: sha256(canonical(value)), proof_identity: null });
    }
    if (area === 'source') {
      const remote = remoteEnvelope(record).source;
      remote.remote ||= input.target.remote;
      if (remote.remote !== input.target.remote) fail('provider attempt remote identity changed');
      if (value.repository) {
        const repository = canonical(value.repository);
        if (remote.repository && canonical(remote.repository) !== repository) fail('provider repository identity changed');
        remote.repository ||= structuredClone(value.repository);
      }
      if (operation === 'source-publish' && value.state === 'PUBLISHED') remote.status = 'published';
      if (operation === 'source-merge' && value.state === 'MERGED') remote.status = 'merged';
    }
    return { attempt, provider: value };
  }, cwd);
  const attempt = remoteSlot(observed.record, area, slotName, repairToken).attempts.find((item) => item.token === preparedAttempt.token);
  return providerAttemptResult(observed, operation, attempt, value);
}

function reconcileExecutingAttempt(recordArg, expectedRecordHash, {
  area, slotName, operation, expectedHead, reconcile, effectStates, absenceStates = [], repairToken = null,
}, cwd) {
  const loaded = readIntegrationRecord(recordArg, cwd);
  if (loaded.hash !== expectedRecordHash) fail('integration record hash is missing or stale');
  const slot = remoteSlot(loaded.record, area, slotName, repairToken);
  const attempt = slot.active_token && slot.attempts.find((item) => item.token === slot.active_token);
  if (!attempt || lastTransition(attempt).state !== 'executing') return null;
  const invocation = lastTransition(attempt).invocation;
  if (invocation.process_instance === PROCESS_INSTANCE && ACTIVE_PROVIDER_INVOCATIONS.has(invocation.token)) {
    return { file: loaded.file, record: loaded.record, hash: loaded.hash,
      result: remoteResult(operation, 'PROVIDER_EXECUTING', { attempt_token: attempt.token }) };
  }
  const observed = providerResult(reconcile(attempt), expectedHead);
  if (effectStates.includes(observed.state)) return withRecord(loaded.file, loaded.hash, (record) => {
    const currentSlot = remoteSlot(record, area, slotName, repairToken); const current = currentSlot.attempts.find((item) => item.token === attempt.token);
    appendAttemptTransition(current, { state: 'observed', at: now(), invocation_token: invocation.token,
      reconciliation: true, result: observed, result_identity: sha256(canonical(observed)) });
    current.disposition = 'proven'; refreshAttempt(current); currentSlot.active_token = null;
    currentSlot.effect = identified({ attempt_identity: current.identity, result_identity: sha256(canonical(observed)), proof_identity: null });
    if (area === 'source') {
      const source = remoteEnvelope(record).source;
      source.remote ||= current.input.target.remote;
      if (source.remote !== current.input.target.remote) fail('provider attempt remote identity changed');
      if (observed.repository) {
        if (source.repository && canonical(source.repository) !== canonical(observed.repository)) {
          fail('provider repository identity changed');
        }
        source.repository ||= structuredClone(observed.repository);
      }
      if (slotName === 'publication') source.status = 'published';
      if (slotName === 'merge') source.status = 'merged';
    }
    const state = operation.endsWith('publish') ? 'PUBLISHED' : domainProviderState(operation, observed.state);
    return remoteResult(operation, state, { attempt_token: current.token,
      provider_state: observed.state, reconciled: true, ...(observed.pr ? { pr: observed.pr } : {}),
      ...(observed.mergeCommit ? { merge_commit: observed.mergeCommit } : {}), ...(observed.remoteBase ? { remote_base: observed.remoteBase } : {}) });
  }, cwd);
  const endedHere = invocation.process_instance === PROCESS_INSTANCE
    && ENDED_PROVIDER_INVOCATIONS.has(invocation.token) && !ACTIVE_PROVIDER_INVOCATIONS.has(invocation.token);
  if (absenceStates.includes(observed.state) && endedHere) return withRecord(loaded.file, loaded.hash, (record) => {
    const current = remoteSlot(record, area, slotName, repairToken).attempts.find((item) => item.token === attempt.token);
    appendAttemptTransition(current, { state: 'prepared', at: now(), replay: identified({
      version: 'remote-provider-replay-proof-v1', invocation_token: invocation.token,
      absence_result: observed, absence_identity: sha256(canonical(observed)), proved_at: now() }) });
    return remoteResult(operation, 'PROVIDER_REPLAYABLE', { attempt_token: current.token, provider_state: observed.state });
  }, cwd);
  return { file: loaded.file, record: loaded.record, hash: loaded.hash,
    result: remoteResult(operation, observed.state === 'MERGE_PENDING' ? 'PENDING' : 'PROVIDER_UNKNOWN', {
      attempt_token: attempt.token, provider_state: observed.state,
    }) };
}

function remoteObservation(provider, target) {
  const result = providerResult(provider.inspect(target), target.expectedHead);
  const remoteBase = Object.hasOwn(result, 'remoteBase')
    ? (OID.test(result.remoteBase || '') ? result.remoteBase : null)
    : observedRemoteBase(target.root, target.remote, target.integrationBranch);
  if (remoteBase === null) fail('provider inspection returned an invalid explicit remote base');
  return { observation: { version: 'remote-provider-observation-v1', repository_identity: result.repository ? sha256(canonical(result.repository)) : null,
    pr_number: result.pr?.number || null, story_branch: target.storyBranch, integration_branch: target.integrationBranch,
    observed_remote_head: result.pr?.headRefOid || null, observed_remote_base: remoteBase,
    result_identity: sha256(canonical(result)) }, result };
}

function maybeSupersedeSourceAttempt(recordArg, expectedRecordHash, slotName, operation, input, fresh, cwd) {
  const loaded = readIntegrationRecord(recordArg, cwd); const slot = remoteSlot(loaded.record, 'source', slotName);
  if (loaded.record.remote.source.merge.effect || loaded.record.remote.source.proof) return null;
  if (slot.active_token) return null;
  const prior = slot.attempts.at(-1); const priorResult = prior && lastTransition(prior)?.result;
  const publishedHeadMayMove = slotName === 'publication' && prior?.disposition === 'proven' && priorResult?.state === 'PUBLISHED';
  if (!prior || lastTransition(prior)?.state !== 'observed'
    || (!publishedHeadMayMove && prior.disposition !== 'active')
    || (!publishedHeadMayMove && !['HEAD_MISMATCH', 'MERGE_PENDING'].includes(priorResult?.state))) return null;
  const freshObservation = input.remote_observation;
  const priorObservation = remoteProviderAttemptObservation(prior);
  if (!priorObservation) return null;
  const desired = ({ remote_observation: _observation, ...rest }) => rest;
  if (canonical(desired(prior.input)) !== canonical(desired(input))) return null;
  const priorPr = priorResult.pr || { number: priorObservation?.pr_number,
    headRefName: priorObservation?.story_branch, baseRefName: priorObservation?.integration_branch,
    headRefOid: priorObservation?.observed_remote_head };
  const headChanged = ((priorResult.state === 'HEAD_MISMATCH' && priorPr.headRefOid !== input.target.expectedHead
    && fresh.pr?.headRefOid === input.target.expectedHead)
    || (publishedHeadMayMove && priorPr.headRefOid === input.target.expectedHead
      && OID.test(fresh.pr?.headRefOid || '') && fresh.pr.headRefOid !== input.target.expectedHead))
    && fresh.pr?.headRefName === priorPr.headRefName && fresh.pr?.baseRefName === priorPr.baseRefName;
  const baseChanged = priorResult.state === 'MERGE_PENDING' && priorObservation && OID.test(priorObservation.observed_remote_base || '')
    && OID.test(freshObservation.observed_remote_base || '')
    && priorObservation.observed_remote_base !== freshObservation.observed_remote_base;
  if (!['READY', 'HEAD_MISMATCH'].includes(fresh.state)
    || fresh.pr?.number !== priorPr.number || !(headChanged || baseChanged)
    || (priorResult.repository && canonical(fresh.repository) !== canonical(priorResult.repository))
    || (!priorResult.repository && freshObservation.repository_identity !== priorObservation?.repository_identity)
    || (priorObservation && (freshObservation.story_branch !== priorObservation.story_branch
      || freshObservation.integration_branch !== priorObservation.integration_branch))) return null;
  return withRecord(loaded.file, expectedRecordHash, (record) => {
    const currentSlot = remoteSlot(record, 'source', slotName); const old = currentSlot.attempts.at(-1); const token = randomUUID();
    const predecessorIdentity = old.identity;
    const predecessorEffect = currentSlot.effect ? structuredClone(currentSlot.effect) : null;
    const priorObservation = remoteProviderAttemptObservation(old);
    const changedFields = ['observed_remote_head', 'observed_remote_base']
      .filter((field) => priorObservation?.[field] !== input.remote_observation?.[field]);
    old.disposition = 'superseded'; old.superseded_by = token;
    const next = { version: 'remote-provider-attempt-v1', token, operation, ordinal: currentSlot.attempts.length,
      input: structuredClone(input), input_identity: sha256(canonical(input)), predecessor_record_hash: expectedRecordHash,
      retry: old.retry, supersedes: old.token, transitions: [], disposition: 'active', superseded_by: null, identity: null };
    appendAttemptTransition(next, { state: 'prepared', at: now(), supersession: identified({
      version: 'remote-provider-supersession-proof-v1', predecessor: old.token,
      predecessor_token: old.token, predecessor_attempt_identity: predecessorIdentity,
      predecessor_effect: predecessorEffect,
      predecessor_effect_identity: predecessorEffect?.identity || null,
      successor_token: token,
      prior_observation_identity: sha256(canonical(priorObservation)),
      current_observation_identity: sha256(canonical(input.remote_observation)),
      changed_fields: changedFields,
      old_head: priorPr.headRefOid, new_head: fresh.pr.headRefOid,
      old_base: priorObservation?.observed_remote_base || null, new_base: freshObservation.observed_remote_base || null,
      pr_number: fresh.pr.number, repository: fresh.repository, proved_at: now() }) });
    currentSlot.attempts.push(next); currentSlot.active_token = token;
    return remoteResult(operation, 'PROVIDER_SUPERSEDED', { predecessor_token: old.token, attempt_token: token });
  }, cwd);
}

export function publishRemoteSource(recordArg, {
  expectedRecordHash, remote = undefined, title, body, createDraft = false, markReady = false,
  provider = createGitHubRemoteAdapter(),
} = {}, cwd = process.cwd()) {
  title = safeRemoteInput(title, 'title', 512);
  body = safeRemoteInput(body, 'body', 1024 * 1024, { multiline: true });
  if (typeof createDraft !== 'boolean' || typeof markReady !== 'boolean') fail('remote draft options must be booleans', 64);
  const loaded = readIntegrationRecord(recordArg, cwd);
  if (loaded.hash !== expectedRecordHash) fail('integration record hash is missing or stale');
  assertRecordSource(loaded.record);
  validateIntegrationProofs(loaded.record);
  const target = sourceTarget(loaded.record, remote);
  const recovered = reconcileExecutingAttempt(loaded.file, loaded.hash, { area: 'source', slotName: 'publication',
    operation: 'source-publish', expectedHead: target.expectedHead, reconcile: () => provider.inspect(target),
    effectStates: ['READY', 'PR_DRAFT', 'CHECKS_PENDING', 'CHECKS_FAILED'], absenceStates: ['PR_ABSENT'] }, cwd);
  if (recovered && recovered.result.state !== 'PROVIDER_REPLAYABLE') return recovered;
  if (recovered) { expectedRecordHash = recovered.hash; recordArg = recovered.file; }
  if (!recovered && (loaded.record.remote?.source?.merge?.effect || loaded.record.remote?.source?.proof)) {
    const retained = loaded.record.remote.source.publication.attempts.at(-1);
    const input = { target, title, body, createDraft, markReady,
      remote_observation: retained?.input?.remote_observation };
    return executeProviderAttempt(loaded.file, loaded.hash, {
      area: 'source', slotName: 'publication', operation: 'source-publish', input,
      expectedHead: target.expectedHead,
      invoke: () => fail('proved source merge cannot issue another publication write'), successStates: ['PUBLISHED'],
    }, cwd);
  }
  const observed = remoteObservation(provider, target);
  const input = { target, title, body, createDraft, markReady, remote_observation: observed.observation };
  const superseded = maybeSupersedeSourceAttempt(recordArg, expectedRecordHash, 'publication', 'source-publish', input, observed.result, cwd);
  if (superseded) return superseded;
  return executeProviderAttempt(recordArg, expectedRecordHash, {
    area: 'source', slotName: 'publication', operation: 'source-publish', input,
    expectedHead: target.expectedHead, invoke: () => provider.publish(target, { title, body, createDraft, markReady }),
    successStates: ['PUBLISHED'],
  }, cwd);
}

export function inspectRemoteSourceReadiness(recordArg, {
  expectedRecordHash, provider = createGitHubRemoteAdapter(),
} = {}, cwd = process.cwd()) {
  const loaded = readIntegrationRecord(recordArg, cwd);
  if (loaded.hash !== expectedRecordHash) fail('integration record hash is missing or stale');
  assertRecordSource(loaded.record);
  validateIntegrationProofs(loaded.record);
  if (loaded.record.remote?.source?.status === 'empty') fail('source publication is not prepared');
  const target = sourceTarget(loaded.record);
  const value = providerResult(provider.inspect(target), target.expectedHead);
  return { file: loaded.file, record: loaded.record, hash: loaded.hash,
    result: remoteResult('source-readiness', domainProviderState('source-readiness', value.state), {
      provider_state: value.state, ...(value.pr ? { pr: value.pr } : {}),
    }) };
}

export function mergeRemoteSource(recordArg, {
  expectedRecordHash, prNumber, method, subject, body, provider = createGitHubRemoteAdapter(),
} = {}, cwd = process.cwd()) {
  if (!Number.isSafeInteger(prNumber) || prNumber <= 0 || !['merge', 'squash', 'rebase'].includes(method)) {
    fail('remote source merge options are invalid', 64);
  }
  subject = safeRemoteInput(subject, 'merge subject', 512);
  body = safeRemoteInput(body, 'merge body', 1024 * 1024, { multiline: true });
  const loaded = readIntegrationRecord(recordArg, cwd);
  if (loaded.hash !== expectedRecordHash) fail('integration record hash is missing or stale');
  if (!loaded.record.remote?.source?.publication?.effect) fail('source pull request publication is not proven');
  const target = sourceTarget(loaded.record);
  const recovered = reconcileExecutingAttempt(loaded.file, loaded.hash, { area: 'source', slotName: 'merge',
    operation: 'source-merge', expectedHead: target.expectedHead,
    reconcile: (attempt) => provider.reconcileMerged(target, { prNumber: attempt.input.prNumber }),
    effectStates: ['MERGED', 'MERGED_BASE_ADVANCED'] }, cwd);
  if (recovered && recovered.result.state !== 'PROVIDER_REPLAYABLE') return recovered;
  if (recovered) { expectedRecordHash = recovered.hash; recordArg = recovered.file; }
  const observed = remoteObservation(provider, target);
  const input = { target, prNumber, method, subject, body, remote_observation: observed.observation };
  const superseded = maybeSupersedeSourceAttempt(recordArg, expectedRecordHash, 'merge', 'source-merge', input, observed.result, cwd);
  if (superseded) return superseded;
  return executeProviderAttempt(recordArg, expectedRecordHash, {
    area: 'source', slotName: 'merge', operation: 'source-merge', input,
    expectedHead: target.expectedHead,
    invoke: () => provider.merge(target, { prNumber, method, subject, body }), successStates: ['MERGED'],
  }, cwd);
}

function singleRemoteUrl(root, remote, push) {
  const args = ['remote', 'get-url', ...(push ? ['--push'] : []), '--all', remote];
  const values = String(git(root, args)).trim().split(/\r?\n/).filter(Boolean);
  if (values.length !== 1) fail(`remote ${remote} must have one ${push ? 'push' : 'fetch'} destination`);
  return values[0];
}

function observedRemoteBase(root, remote, remoteBranch) {
  const output = String(git(root, ['ls-remote', '--refs', remote, `refs/heads/${remoteBranch}`])).trim().split(/\r?\n/).filter(Boolean);
  const match = output.length === 1 ? /^([0-9a-f]{40}(?:[0-9a-f]{24})?)\trefs\/heads\/(.+)$/.exec(output[0]) : null;
  if (!match || match[2] !== remoteBranch) fail('remote integration base is not one exact full object id');
  return match[1];
}

function assertFetchPushIdentity(root, remote) {
  if (singleRemoteUrl(root, remote, false) !== singleRemoteUrl(root, remote, true)) {
    fail('remote fetch and push destinations differ');
  }
}

function defaultFetchRemote({ root, remote, branch: remoteBranch, proofRef }) {
  assertFetchPushIdentity(root, remote);
  try { git(root, ['show-ref', '--verify', '--quiet', proofRef]); fail('remote proof ref already exists'); }
  catch (error) { if (error instanceof DeliverError && !/Git cannot/.test(error.message)) throw error; }
  git(root, ['fetch', '--no-tags', '--no-write-fetch-head', remote, `refs/heads/${remoteBranch}:${proofRef}`]);
  return { state: 'FETCHED', oid: String(git(root, ['rev-parse', '--verify', proofRef])).trim() };
}

function assertCommit(root, oid, label) {
  if (!OID.test(oid || '')) fail(`${label} is not a full object id`);
  try { git(root, ['cat-file', '-e', `${oid}^{commit}`]); } catch { fail(`${label} is not a commit object`); }
}

function isAncestor(root, older, newer) {
  const result = spawnSync('git', ['-C', root, 'merge-base', '--is-ancestor', older, newer], {
    stdio: 'ignore', timeout: 30000, windowsHide: true,
  });
  if (result.status === 0) return true;
  if (result.status === 1) return false;
  fail('Git could not prove remote commit ancestry');
}

export function reconcileRemoteSource(recordArg, {
  expectedRecordHash, prNumber, provider = createGitHubRemoteAdapter(), fetchRemote = defaultFetchRemote,
} = {}, cwd = process.cwd()) {
  if (!Number.isSafeInteger(prNumber) || prNumber <= 0 || typeof fetchRemote !== 'function') fail('remote source reconcile options are invalid', 64);
  let loaded = readIntegrationRecord(recordArg, cwd);
  if (loaded.hash !== expectedRecordHash) fail('integration record hash is missing or stale');
  let target = sourceTarget(loaded.record);
  if (!loaded.record.remote?.source?.merge?.effect && loaded.record.remote?.source?.merge?.active_token) {
    const recovered = reconcileExecutingAttempt(loaded.file, loaded.hash, {
      area: 'source', slotName: 'merge', operation: 'source-merge', expectedHead: target.expectedHead,
      reconcile: (attempt) => provider.reconcileMerged(target, { prNumber: attempt.input.prNumber }),
      effectStates: ['MERGED', 'MERGED_BASE_ADVANCED'],
    }, cwd);
    if (recovered && recovered.hash === loaded.hash) return recovered;
    if (recovered) {
      loaded = readIntegrationRecord(recovered.file, cwd);
      target = sourceTarget(loaded.record);
    }
  }
  assertFetchPushIdentity(target.root, target.remote);
  const value = providerResult(provider.reconcileMerged(target, { prNumber }), target.expectedHead);
  if (!['MERGED', 'MERGED_BASE_ADVANCED'].includes(value.state)) {
    return { file: loaded.file, record: loaded.record, hash: loaded.hash,
      result: remoteResult('source-reconcile', domainProviderState('source-reconcile', value.state), { provider_state: value.state }) };
  }
  if (!OID.test(value.remoteBase || '')) fail('provider remote base is invalid');
  const token = randomUUID();
  const proofRef = `refs/deliver/remote-evidence/${loaded.record.id}/${token}`;
  const fetchResult = fetchRemote({ root: target.root, remote: target.remote,
    branch: target.integrationBranch, proofRef, expectedRemoteOid: value.remoteBase });
  const fetched = String(git(target.root, ['rev-parse', '--verify', proofRef])).trim();
  if (fetched !== value.remoteBase || fetchResult?.oid !== value.remoteBase) fail('fetched proof ref does not match the provider remote base');
  assertCommit(target.root, fetched, 'fetched remote base');
  assertCommit(target.root, value.mergeCommit, 'provider merge commit');
  if (value.state === 'MERGED' && fetched !== value.mergeCommit) fail('exact merge reconciliation returned a different remote base');
  if (value.state === 'MERGED_BASE_ADVANCED' && !isAncestor(target.root, value.mergeCommit, fetched)) {
    fail('advanced remote base does not descend from the source merge commit');
  }
  const mergeAttempt = loaded.record.remote?.source?.merge?.attempts?.at(-1);
  const method = mergeAttempt?.input?.method;
  if (!['merge', 'squash', 'rebase'].includes(method)) fail('source merge method was not retained');
  const base = loaded.record.integration.base;
  const candidate = loaded.record.source.candidate;
  const premergeBase = mergeAttempt.input?.remote_observation?.observed_remote_base;
  assertCommit(target.root, premergeBase, 'retained premerge base');
  if (!isAncestor(target.root, base, premergeBase)) fail('retained premerge base does not descend from approved I');
  const parents = String(git(target.root, ['rev-list', '--parents', '-n', '1', value.mergeCommit])).trim().split(/\s+/).slice(1);
  if (method === 'merge' && (parents.length !== 2 || parents[0] !== premergeBase || parents[1] !== candidate
    || tree(target.root, value.mergeCommit) !== expectedMergeTree(target.root, premergeBase, candidate))) {
    fail('remote merge does not have exact N/C parents and composition');
  }
  if (method === 'squash') {
    const sourceBases = String(git(target.root, ['merge-base', '--all', premergeBase, candidate])).trim().split(/\r?\n/).filter(Boolean);
    if (sourceBases.length !== 1) fail('source squash lineage does not have a unique merge base');
    const sourcePaths = String(git(target.root, ['diff', '--name-only', sourceBases[0], candidate, '--'])).trim().split(/\r?\n/).filter(Boolean).sort();
    const squashPaths = String(git(target.root, ['diff', '--name-only', premergeBase, value.mergeCommit, '--'])).trim().split(/\r?\n/).filter(Boolean).sort();
    if (parents.length !== 1 || parents[0] !== premergeBase || sourcePaths.length > 10000
      || canonical(sourcePaths) !== canonical(squashPaths)
      || tree(target.root, value.mergeCommit) !== expectedMergeTree(target.root, premergeBase, candidate)) {
      fail('remote squash is not the exact bounded N/C composition');
    }
  }
  if (method === 'rebase') {
    const rebaseBase = premergeBase;
    assertCommit(target.root, rebaseBase, 'retained premerge base');
    if (parents.length !== 1 || !isAncestor(target.root, rebaseBase, value.mergeCommit)) {
      fail('remote rebase does not descend from its retained premerge base');
    }
    const bases = String(git(target.root, ['merge-base', '--all', rebaseBase, value.mergeCommit])).trim().split(/\r?\n/).filter(Boolean);
    const chain = String(git(target.root, ['rev-list', '--first-parent', `${rebaseBase}..${value.mergeCommit}`])).trim().split(/\r?\n/).filter(Boolean);
    const sourceBases = String(git(target.root, ['merge-base', '--all', rebaseBase, candidate])).trim().split(/\r?\n/).filter(Boolean);
    if (sourceBases.length !== 1) fail('source lineage does not have a unique merge base');
    const sourcePaths = String(git(target.root, ['diff', '--name-only', sourceBases[0], candidate, '--'])).trim().split(/\r?\n/).filter(Boolean).sort();
    const rebasedPaths = String(git(target.root, ['diff', '--name-only', rebaseBase, value.mergeCommit, '--'])).trim().split(/\r?\n/).filter(Boolean).sort();
    const sourceSet = new Set(sourcePaths);
    const boundedCommits = chain.every((commit) => {
      const changed = String(git(target.root, ['diff-tree', '--no-commit-id', '--name-only', '-r', `${commit}^`, commit, '--'])).trim().split(/\r?\n/).filter(Boolean);
      return changed.every((rel) => sourceSet.has(rel));
    });
    if (bases.length !== 1 || bases[0] !== rebaseBase || !chain.length || chain.length > 10000 || !boundedCommits
      || tree(target.root, value.mergeCommit) !== expectedMergeTree(target.root, rebaseBase, candidate)
      || canonical(sourcePaths) !== canonical(rebasedPaths)) fail('remote rebase lacks a bounded unique first-parent source delta');
  }
  return withRecord(loaded.file, loaded.hash, (record) => {
    const proof = identified({ version: 'remote-source-proof-v1', provider_state: value.state,
      repository: structuredClone(value.repository || record.remote.source.repository), pr_number: prNumber,
      method, source_merge_commit: value.mergeCommit, verified_integration_commit: fetched,
      proof_ref: proofRef, evidence_token: token,
      evidence_branch: `pm/${record.source.story}-remote-evidence-${token}`, proved_at: now() });
    record.remote.source.status = 'proven';
    record.remote.source.proof = proof;
    return remoteResult('source-reconcile', value.state === 'MERGED' ? 'LINEAGE_PROVEN' : 'SOURCE_BASE_ADVANCED', {
      provider_state: value.state, source_merge_commit: value.mergeCommit,
      verified_integration_commit: fetched, proof_ref: proofRef,
      evidence_branch: proof.evidence_branch,
    });
  }, cwd);
}

function remoteEvidenceRoot(record) {
  const evidence = record.remote?.integration_evidence;
  if (!evidence || evidence.status === 'prepared') fail('remote integration evidence checkout is not prepared');
  const root = rootPath(evidence.root);
  if (commonRepository(root) !== record.destination.common_repository || branch(root) !== evidence.branch
    || head(root) !== evidence.commit) fail('remote evidence checkout no longer identifies fetched M');
  assertClean(root); assertOrdinaryIndex(root);
  verifyCheckoutProof(root, evidence.commit, evidence.checkout_proof, evidence.anchor);
  return root;
}

export function prepareRemoteIntegrationEvidence(recordArg, {
  expectedRecordHash, evidenceRoot,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const proof = record.remote?.source?.proof;
    if (!proof) fail('proved remote source lineage is required');
    const root = rootPath(evidenceRoot);
    const existing = record.remote.integration_evidence;
    if (existing) {
      if (existing.root !== root || existing.branch !== proof.evidence_branch
        || existing.commit !== proof.verified_integration_commit) fail('remote evidence resume differs from retained checkout');
      remoteEvidenceRoot(record);
      return { [NO_MUTATION]: true, value: remoteResult('remote-evidence-prepare', 'REMOTE_EVIDENCE_PREPARED', {
        root, branch: existing.branch, commit: existing.commit, snapshot_hash: existing.snapshot_hash }) };
    }
    if (commonRepository(root) !== record.destination.common_repository || branch(root) !== proof.evidence_branch
      || head(root) !== proof.verified_integration_commit) fail('remote evidence checkout does not match its allocated branch and M');
    assertClean(root); assertOrdinaryIndex(root);
    const attachments = String(git(root, ['worktree', 'list', '--porcelain'])).split(/\r?\n/)
      .filter((line) => line === `branch refs/heads/${proof.evidence_branch}`).length;
    if (attachments !== 1) fail('remote evidence branch must have one exact worktree attachment');
    const anchor = captureGitAnchor(root);
    const checkoutProof = buildCheckoutProof(root, proof.verified_integration_commit, anchor);
    verifyCheckoutProof(root, proof.verified_integration_commit, checkoutProof, anchor);
    const manifest = boundManifest(root, proof.verified_integration_commit, record.source.packet,
      record.source.story_path, record.integration.manifest.bindings);
    record.remote.integration_evidence = {
      version: 'remote-integration-evidence-v1', status: 'ready', root, branch: proof.evidence_branch,
      commit: proof.verified_integration_commit, anchor, checkout_proof: checkoutProof, manifest,
      source_reusable: manifest.hash === record.integration.manifest.hash,
      snapshot_hash: sha256(canonical({ commit: proof.verified_integration_commit, manifest: manifest.hash,
        anchor: sha256(canonical(anchor)), checkout: sha256(canonical(checkoutProof)) })),
      gates: [], gate_history: [], review: null, review_history: [], verification: null,
      verification_history: [], finalized: false, finalization: null, prepared_at: now(),
    };
    return remoteResult('remote-evidence-prepare', 'REMOTE_EVIDENCE_PREPARED', {
      root, branch: proof.evidence_branch, commit: proof.verified_integration_commit,
      snapshot_hash: record.remote.integration_evidence.snapshot_hash,
    });
  }, cwd);
}

export function runRemoteIntegrationGate(recordArg, { expectedRecordHash, name } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence;
    assertRemoteEvidenceMutable(record);
    const root = remoteEvidenceRoot(record);
    const command = record.source.packet.commands?.[name];
    if (typeof command !== 'string') fail('remote integration gate is not declared by the source task');
    const started = now();
    const result = spawnSync(command, { cwd: root, shell: true, encoding: 'utf8', timeout: 10 * 60 * 1000,
      maxBuffer: 1024 * 1024, windowsHide: true });
    let stable = true; try { remoteEvidenceRoot(record); } catch { stable = false; }
    const logDir = internalDirectory(root, ['logs', `remote-integration-${record.id}`]);
    const log = path.join(logDir, `${name}-${randomUUID()}.log`);
    const logText = `command: ${command}\nstarted: ${started}\nexit: ${result.status}\n\n[stdout]\n${result.stdout || ''}\n[stderr]\n${result.stderr || ''}`;
    fs.writeFileSync(log, logText, { flag: 'wx', mode: 0o600 });
    const receipt = identified({ provenance: 'deliver-remote-integration-gate-v1', name, command,
      integration_commit: evidence.commit, snapshot_hash: evidence.snapshot_hash,
      status: result.status === 0 && !result.error && stable ? 'PASS' : 'FAIL', exit_code: result.status,
      signal: result.signal || null, error: result.error?.message || null, started_at: started, finished_at: now(),
      log_path: path.relative(root, log).split(path.sep).join('/'), log_hash: sha256(logText) });
    const previous = evidence.gates.find((item) => item.name === name);
    if (previous) evidence.gate_history.push(previous);
    evidence.gates = evidence.gates.filter((item) => item.name !== name); evidence.gates.push(receipt);
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-gate', receipt.status === 'PASS' ? 'PASSED' : 'FAILED', { receipt });
  }, cwd);
}

export function recordRemoteIntegrationReview(recordArg, {
  expectedRecordHash, reviewer, receipt,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence; remoteEvidenceRoot(record);
    assertRemoteEvidenceMutable(record);
    if (!ACTOR_ID.test(reviewer || '') || reviewer === record.source.builder) fail('remote integration reviewer must differ from the builder');
    const parsed = parseReviewReceipt(receipt, { expectedSnapshot: evidence.snapshot_hash });
    const value = identified({ ...parsed, reviewer, snapshot_hash: evidence.snapshot_hash, recorded_at: now() });
    if (evidence.review) evidence.review_history.push(evidence.review); evidence.review = value;
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-review', 'RECORDED', { receipt: value });
  }, cwd);
}

export function recordRemoteIntegrationVerification(recordArg, {
  expectedRecordHash, verifier, results,
} = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const evidence = record.remote?.integration_evidence; remoteEvidenceRoot(record);
    assertRemoteEvidenceMutable(record);
    const reviewers = new Set([evidence.review?.reviewer, ...(evidence.review?.panel?.members || []).map((item) => item.reviewer)]);
    if (!ACTOR_ID.test(verifier || '') || verifier === record.source.builder || reviewers.has(verifier)) fail('remote integration verifier is not independent');
    const criteria = parseVerificationResults(results, record.source.packet.acceptance);
    const value = identified({ verifier, criteria, snapshot_hash: evidence.snapshot_hash, recorded_at: now() });
    if (evidence.verification) evidence.verification_history.push(evidence.verification); evidence.verification = value;
    evidence.finalized = false; evidence.finalization = null;
    return remoteResult('remote-evidence-verification', 'RECORDED', { receipt: value });
  }, cwd);
}

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { DeliverError } from './state.mjs';

export const GITHUB_REMOTE_STAGES = Object.freeze([
  'preflight', 'lookup', 'publish', 'checks', 'merge', 'postmerge',
]);

export const GITHUB_REMOTE_STATES = Object.freeze([
  'UNAVAILABLE',
  'GIT_ERROR',
  'REMOTE_MISSING',
  'REMOTE_AMBIGUOUS',
  'UNSUPPORTED_REMOTE',
  'AUTH_REQUIRED',
  'HEAD_MISMATCH',
  'PR_ABSENT',
  'PR_AMBIGUOUS',
  'PR_LOOKUP_INCOMPLETE',
  'PR_LOOKUP_FAILED',
  'PR_CLOSED',
  'PR_MERGED',
  'PR_DRAFT',
  'CHECKS_PENDING',
  'CHECKS_FAILED',
  'CHECKS_UNKNOWN',
  'READY',
  'PUSH_REJECTED',
  'PR_WRITE_FAILED',
  'PR_READY_FAILED',
  'PUBLISHED',
  'MERGE_REJECTED',
  'MERGE_PENDING',
  'MERGE_MISMATCH',
  'MERGED',
  'MERGED_BASE_ADVANCED',
  'UNKNOWN',
]);

const MAX_OUTPUT_BYTES = 2 * 1024 * 1024;
const MAX_BODY_BYTES = 1024 * 1024;
const MAX_PROVIDER_ITEMS = 100;
const LIST_FIELDS = 'number,state,isDraft,headRefName,headRefOid,baseRefName,headRepositoryOwner,url,mergeCommit';
const VIEW_FIELDS = `${LIST_FIELDS},mergeable,mergeStateStatus`;
const CHECK_FIELDS = 'name,state,bucket,workflow';
const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const SAFE_REMOTE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
const SAFE_REPOSITORY_PART = /^[A-Za-z0-9](?:[A-Za-z0-9_.-]{0,98}[A-Za-z0-9])?$/;
const SAFE_HOST = /^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)(?:\.(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?))*$/;
const NO_CHECKS = (branch) => new Set([
  `no checks reported on the '${branch}' branch`,
  `no required checks reported on the '${branch}' branch`,
]);

const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const byteLength = (value) => Buffer.byteLength(value, 'utf8');

function invalid(message, code = 64) {
  throw new DeliverError(message, code);
}

function safeBranch(value, label) {
  if (typeof value !== 'string' || !value || value.length > 512 || value === '@'
    || value.startsWith('-') || value.startsWith('/') || value.endsWith('/') || value.endsWith('.')
    || value.includes('..') || value.includes('//') || value.includes('@{')
    || /[\x00-\x20\x7f~^:?*[\\\]]/.test(value)
    || value.split('/').some((part) => !part || part.startsWith('.') || part.endsWith('.lock'))) {
    invalid(`${label} must be a valid Git branch name`);
  }
  return value;
}

function boundedLine(value, label, max = 512) {
  if (typeof value !== 'string' || !value.trim() || value.length > max || /[\x00-\x1f\x7f]/.test(value)) {
    invalid(`${label} must be a bounded non-empty single line`);
  }
  return value;
}

function boundedBody(value, label) {
  if (typeof value !== 'string' || value.includes('\0') || byteLength(value) > MAX_BODY_BYTES) {
    invalid(`${label} must be bounded UTF-8 text without null bytes`);
  }
  return value;
}

function realRoot(root) {
  if (typeof root !== 'string' || !root || root.includes('\0')) invalid('target root must be a path', 66);
  try {
    const stat = fs.lstatSync(root);
    if (!stat.isDirectory() || stat.isSymbolicLink()) invalid('target root must be a real directory', 66);
    return fs.realpathSync.native(root);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    invalid(`target root is unavailable: ${error.message}`, 66);
  }
}

function validateTarget(target) {
  if (!record(target)) invalid('target must be an object');
  const allowed = new Set(['root', 'remote', 'storyBranch', 'integrationBranch', 'expectedHead']);
  const unknown = Object.keys(target).filter((key) => !allowed.has(key));
  if (unknown.length) invalid(`unsupported target fields: ${unknown.join(', ')}`);
  const root = realRoot(target.root);
  if (typeof target.remote !== 'string' || !SAFE_REMOTE.test(target.remote) || target.remote.startsWith('-')) {
    invalid('target remote must be an explicit safe Git remote name');
  }
  const storyBranch = safeBranch(target.storyBranch, 'storyBranch');
  const integrationBranch = safeBranch(target.integrationBranch, 'integrationBranch');
  if (storyBranch === integrationBranch) invalid('storyBranch must differ from integrationBranch');
  if (typeof target.expectedHead !== 'string' || !OID.test(target.expectedHead)) {
    invalid('expectedHead must be a full lowercase Git object ID');
  }
  return { root, remote: target.remote, storyBranch, integrationBranch, expectedHead: target.expectedHead };
}

function diagnostic(code, message) {
  return { code, message };
}

function result(target, stage, state, extra = {}) {
  return { stage, state, expectedHead: target.expectedHead, ...extra };
}

export function runCommand({ file, args, cwd, input, timeoutMs }) {
  const child = spawnSync(file, args, {
    cwd,
    input,
    encoding: 'utf8',
    timeout: timeoutMs,
    maxBuffer: MAX_OUTPUT_BYTES,
    shell: false,
    windowsHide: true,
    stdio: ['pipe', 'pipe', 'pipe'],
    env: {
      ...process.env,
      GIT_TERMINAL_PROMPT: '0',
      GH_PROMPT_DISABLED: '1',
    },
  });
  return {
    exitCode: child.status,
    stdout: child.stdout || '',
    stderr: child.stderr || '',
    ...(child.error ? { errorCode: child.error.code || 'COMMAND_ERROR' } : {}),
  };
}

function command(run, timeoutMs, file, args, cwd, input) {
  let value;
  try {
    value = run({ file, args: [...args], cwd, ...(input === undefined ? {} : { input }), timeoutMs });
  } catch (error) {
    return {
      exitCode: null,
      stdout: '',
      stderr: '',
      errorCode: error?.code === 'ENOENT' ? 'ENOENT' : 'COMMAND_THROW',
    };
  }
  if (!record(value) || !(value.exitCode === null || Number.isInteger(value.exitCode))
    || typeof value.stdout !== 'string' || typeof value.stderr !== 'string'
    || (value.errorCode !== undefined && typeof value.errorCode !== 'string')) {
    return { exitCode: null, stdout: '', stderr: '', errorCode: 'INVALID_RUNNER_RESULT' };
  }
  if (byteLength(value.stdout) + byteLength(value.stderr) > MAX_OUTPUT_BYTES) {
    return { exitCode: null, stdout: '', stderr: '', errorCode: 'OUTPUT_LIMIT' };
  }
  return value;
}

function commandFailure(target, stage, file, invocation, fallbackState, fallbackCode, fallbackMessage) {
  if (!invocation.errorCode) return null;
  if (invocation.errorCode === 'ENOENT') return result(target, stage, 'UNAVAILABLE', {
    diagnostic: diagnostic(file === 'git' ? 'GIT_UNAVAILABLE' : 'GH_UNAVAILABLE', `${file} is unavailable.`),
  });
  return result(target, stage, file === 'git' ? 'GIT_ERROR' : fallbackState, {
    diagnostic: diagnostic(
      invocation.errorCode === 'OUTPUT_LIMIT' ? 'COMMAND_OUTPUT_LIMIT' : fallbackCode,
      invocation.errorCode === 'OUTPUT_LIMIT' ? 'Command output exceeded the adapter limit.' : fallbackMessage,
    ),
  });
}

function trimOneLineEnding(value) {
  return value.replace(/\r\n/g, '\n').replace(/\n$/, '');
}

function repositoryPart(value) {
  return SAFE_REPOSITORY_PART.test(value) && value !== '.' && value !== '..';
}

function repository(host, owner, name) {
  if (!SAFE_HOST.test(host) || !repositoryPart(owner) || !repositoryPart(name)) return null;
  const canonicalHost = host.toLowerCase();
  const canonicalOwner = owner.toLowerCase();
  const canonicalName = name.toLowerCase();
  return {
    host: canonicalHost,
    owner: canonicalOwner,
    name: canonicalName,
    slug: `${canonicalHost}/${canonicalOwner}/${canonicalName}`,
  };
}

function parseRemoteUrl(raw) {
  if (typeof raw !== 'string' || !raw || /[\x00-\x20\x7f]/.test(raw)) return null;
  const scp = /^git@([^/:]+):([^/]+)\/([^/]+)$/.exec(raw);
  if (scp) {
    const name = scp[3].endsWith('.git') ? scp[3].slice(0, -4) : scp[3];
    return repository(scp[1], scp[2], name);
  }
  let parsed;
  try { parsed = new URL(raw); } catch { return null; }
  if (!['https:', 'ssh:'].includes(parsed.protocol) || parsed.port || parsed.search || parsed.hash) return null;
  if (parsed.protocol === 'https:' && (parsed.username || parsed.password)) return null;
  if (parsed.protocol === 'ssh:' && parsed.username && parsed.username !== 'git') return null;
  if (parsed.password || parsed.pathname.includes('%')) return null;
  const parts = parsed.pathname.split('/').filter(Boolean);
  if (parts.length !== 2) return null;
  const name = parts[1].endsWith('.git') ? parts[1].slice(0, -4) : parts[1];
  return repository(parsed.hostname, parts[0], name);
}

function preflight(targetInput, run, timeoutMs) {
  const target = validateTarget(targetInput);
  const remote = command(run, timeoutMs, 'git', ['remote', 'get-url', '--push', '--all', target.remote], target.root);
  const remoteFailure = commandFailure(target, 'preflight', 'git', remote, 'GIT_ERROR', 'REMOTE_LOOKUP_ERROR', 'Git could not inspect the configured remote.');
  if (remoteFailure) return { target, failure: remoteFailure };
  if (remote.exitCode !== 0) {
    const listed = command(run, timeoutMs, 'git', ['remote'], target.root);
    const listedFailure = commandFailure(target, 'preflight', 'git', listed, 'GIT_ERROR', 'REMOTE_LIST_ERROR', 'Git could not list configured remotes.');
    if (listedFailure) return { target, failure: listedFailure };
    if (listed.exitCode === 0) {
      const names = trimOneLineEnding(listed.stdout).split('\n').filter(Boolean);
      if (names.every((name) => SAFE_REMOTE.test(name)) && !names.includes(target.remote)) {
        return { target, failure: result(target, 'preflight', 'REMOTE_MISSING', {
          diagnostic: diagnostic('REMOTE_NOT_FOUND', 'The selected Git remote does not exist.'),
        }) };
      }
    }
    return { target, failure: result(target, 'preflight', 'GIT_ERROR', {
      diagnostic: diagnostic('REMOTE_LOOKUP_FAILED', 'Git could not inspect the configured remote.'),
    }) };
  }
  const urls = trimOneLineEnding(remote.stdout).split('\n').filter((line) => line.length > 0);
  if (urls.length === 0) return { target, failure: result(target, 'preflight', 'REMOTE_MISSING', {
    diagnostic: diagnostic('REMOTE_URL_MISSING', 'The selected remote has no push URL.'),
  }) };
  if (urls.length !== 1) return { target, failure: result(target, 'preflight', 'REMOTE_AMBIGUOUS', {
    diagnostic: diagnostic('REMOTE_URL_COUNT', 'The selected remote must have exactly one push URL.'),
  }) };
  const repo = parseRemoteUrl(urls[0]);
  if (!repo) return { target, failure: result(target, 'preflight', 'UNSUPPORTED_REMOTE', {
    diagnostic: diagnostic('REMOTE_URL_UNSUPPORTED', 'The push URL is not an uncredentialed GitHub HTTPS or SSH repository URL.'),
  }) };
  const fetchRemote = command(run, timeoutMs, 'git', ['remote', 'get-url', '--all', target.remote], target.root);
  const fetchFailure = commandFailure(target, 'preflight', 'git', fetchRemote, 'GIT_ERROR', 'REMOTE_LOOKUP_ERROR', 'Git could not inspect the configured fetch remote.');
  if (fetchFailure) return { target, failure: fetchFailure };
  const fetchUrls = trimOneLineEnding(fetchRemote.stdout).split('\n').filter((line) => line.length > 0);
  if (fetchRemote.exitCode !== 0 || fetchUrls.length !== 1 || fetchUrls[0] !== urls[0]) {
    return { target, failure: result(target, 'preflight', 'REMOTE_AMBIGUOUS', {
      repository: repo,
      diagnostic: diagnostic('REMOTE_FETCH_PUSH_MISMATCH', 'The selected remote must have one identical fetch and push destination.'),
    }) };
  }

  const branch = command(run, timeoutMs, 'git', ['symbolic-ref', '--quiet', '--short', 'HEAD'], target.root);
  const branchFailure = commandFailure(target, 'preflight', 'git', branch, 'GIT_ERROR', 'CHECKOUT_PROBE_ERROR', 'Git could not inspect the checked-out branch.');
  if (branchFailure) return { target, failure: branchFailure };
  if (branch.exitCode !== 0) return { target, failure: result(target, 'preflight', 'GIT_ERROR', {
    repository: repo,
    diagnostic: diagnostic('CHECKOUT_NOT_SYMBOLIC', 'The target checkout is detached or unreadable.'),
  }) };
  if (trimOneLineEnding(branch.stdout) !== target.storyBranch) return { target, failure: result(target, 'preflight', 'HEAD_MISMATCH', {
    repository: repo,
    diagnostic: diagnostic('CHECKOUT_BRANCH_MISMATCH', 'The checked-out branch does not match storyBranch.'),
  }) };

  const head = command(run, timeoutMs, 'git', ['rev-parse', '--verify', 'HEAD'], target.root);
  const headFailure = commandFailure(target, 'preflight', 'git', head, 'GIT_ERROR', 'HEAD_PROBE_ERROR', 'Git could not resolve the checked-out commit.');
  if (headFailure) return { target, failure: headFailure };
  if (head.exitCode !== 0 || !OID.test(trimOneLineEnding(head.stdout))) return { target, failure: result(target, 'preflight', 'GIT_ERROR', {
    repository: repo,
    diagnostic: diagnostic('HEAD_UNREADABLE', 'Git did not return a full commit object ID.'),
  }) };
  if (trimOneLineEnding(head.stdout) !== target.expectedHead) return { target, failure: result(target, 'preflight', 'HEAD_MISMATCH', {
    repository: repo,
    diagnostic: diagnostic('LOCAL_HEAD_MISMATCH', 'The checked-out commit differs from expectedHead.'),
  }) };

  const auth = command(run, timeoutMs, 'gh', ['auth', 'status', '--active', '--hostname', repo.host], target.root);
  const authFailure = commandFailure(target, 'preflight', 'gh', auth, 'AUTH_REQUIRED', 'AUTH_PROBE_ERROR', 'GitHub authentication could not be checked.');
  if (authFailure) return { target, failure: authFailure };
  if (auth.exitCode !== 0) return { target, failure: result(target, 'preflight', 'AUTH_REQUIRED', {
    repository: repo,
    diagnostic: diagnostic('GH_AUTH_REQUIRED', 'Active GitHub CLI authentication is required for this host.'),
  }) };
  return { target, repo };
}

function parseJson(invocation) {
  try { return JSON.parse(invocation.stdout); } catch { return null; }
}

function safeProviderString(value, max = 1000) {
  return typeof value === 'string' && value.length <= max && !/[\x00-\x1f\x7f]/.test(value);
}

function normalizePr(value, repo) {
  if (!record(value) || !Number.isSafeInteger(value.number) || value.number <= 0
    || !['OPEN', 'CLOSED', 'MERGED'].includes(value.state) || typeof value.isDraft !== 'boolean'
    || !safeProviderString(value.headRefName, 512) || !safeProviderString(value.headRefOid, 64) || !OID.test(value.headRefOid)
    || !safeProviderString(value.baseRefName, 512) || !record(value.headRepositoryOwner)
    || !safeProviderString(value.headRepositoryOwner.login, 100)
    || !(value.url === null || safeProviderString(value.url, 2048))
    || !(value.mergeCommit === null || (record(value.mergeCommit) && safeProviderString(value.mergeCommit.oid, 64)
      && OID.test(value.mergeCommit.oid)))) return null;
  const owner = value.headRepositoryOwner.login.toLowerCase();
  let url = null;
  if (value.url) {
    try {
      const parsed = new URL(value.url);
      if (parsed.protocol === 'https:' && !parsed.username && !parsed.password
        && parsed.hostname.toLowerCase() === repo.host) url = value.url;
    } catch {}
  }
  return {
    number: value.number,
    state: value.state,
    isDraft: value.isDraft,
    headRefName: value.headRefName,
    headRefOid: value.headRefOid,
    baseRefName: value.baseRefName,
    headRepositoryOwner: owner,
    url,
    mergeCommit: value.mergeCommit,
    ...(value.mergeable === undefined ? {} : { mergeable: value.mergeable }),
    ...(value.mergeStateStatus === undefined ? {} : { mergeStateStatus: value.mergeStateStatus }),
  };
}

function publicPr(pr) {
  return {
    number: pr.number,
    state: pr.state,
    isDraft: pr.isDraft,
    headRefName: pr.headRefName,
    headRefOid: pr.headRefOid,
    baseRefName: pr.baseRefName,
    url: pr.url,
  };
}

function lookup(target, repo, run, timeoutMs, { allowStaleHead = false } = {}) {
  const args = ['pr', 'list', '--repo', repo.slug, '--state', 'all', '--head', target.storyBranch,
    '--base', target.integrationBranch, '--limit', String(MAX_PROVIDER_ITEMS), '--json', LIST_FIELDS];
  const invocation = command(run, timeoutMs, 'gh', args, target.root);
  const failure = commandFailure(target, 'lookup', 'gh', invocation, 'PR_LOOKUP_FAILED', 'PR_LOOKUP_ERROR', 'The pull request lookup could not be completed.');
  if (failure) return { failure };
  if (invocation.exitCode !== 0) return { failure: result(target, 'lookup', 'PR_LOOKUP_FAILED', {
    repository: repo,
    diagnostic: diagnostic('PR_LOOKUP_FAILED', 'The pull request lookup could not be completed.'),
  }) };
  const parsed = parseJson(invocation);
  if (!Array.isArray(parsed) || parsed.length > MAX_PROVIDER_ITEMS) return { failure: result(target, 'lookup', 'PR_LOOKUP_FAILED', {
    repository: repo,
    diagnostic: diagnostic('PR_LOOKUP_MALFORMED', 'The pull request lookup returned malformed JSON.'),
  }) };
  if (parsed.length === MAX_PROVIDER_ITEMS) return { failure: result(target, 'lookup', 'PR_LOOKUP_INCOMPLETE', {
    repository: repo,
    diagnostic: diagnostic('PR_LOOKUP_LIMIT', 'The pull request lookup reached its page limit and is incomplete.'),
  }) };
  const normalized = parsed.map((item) => normalizePr(item, repo));
  if (normalized.some((item) => item === null)) return { failure: result(target, 'lookup', 'PR_LOOKUP_FAILED', {
    repository: repo,
    diagnostic: diagnostic('PR_LOOKUP_MALFORMED', 'The pull request lookup returned invalid fields.'),
  }) };
  const matches = normalized.filter((pr) => pr.headRepositoryOwner === repo.owner
    && pr.headRefName === target.storyBranch && pr.baseRefName === target.integrationBranch);
  if (!matches.length) return { failure: result(target, 'lookup', 'PR_ABSENT', {
    repository: repo,
    diagnostic: diagnostic('PR_NOT_FOUND', 'No exact pull request exists for this repository, head and base.'),
  }) };
  if (matches.length !== 1) return { failure: result(target, 'lookup', 'PR_AMBIGUOUS', {
    repository: repo,
    diagnostic: diagnostic('PR_MULTIPLE_MATCHES', 'More than one exact pull request matches this head and base.'),
  }) };
  const pr = matches[0];
  if (pr.state === 'MERGED') return { failure: result(target, 'lookup', 'PR_MERGED', { repository: repo, pr: publicPr(pr) }) };
  if (pr.state !== 'OPEN') return { failure: result(target, 'lookup', 'PR_CLOSED', { repository: repo, pr: publicPr(pr) }) };
  if (!allowStaleHead && pr.headRefOid !== target.expectedHead) return { failure: result(target, 'lookup', 'HEAD_MISMATCH', {
    repository: repo,
    pr: publicPr(pr),
    diagnostic: diagnostic('PR_HEAD_MISMATCH', 'The pull request head differs from expectedHead.'),
  }) };
  return { pr };
}

function view(target, repo, prNumber, run, timeoutMs, {
  allowMerged = false, stage = 'lookup', requireMergeability = true,
} = {}) {
  const invocation = command(run, timeoutMs, 'gh', ['pr', 'view', String(prNumber), '--repo', repo.slug, '--json', VIEW_FIELDS], target.root);
  const failure = commandFailure(target, stage, 'gh', invocation, 'PR_LOOKUP_FAILED', 'PR_VIEW_ERROR', 'The pull request could not be read.');
  if (failure) return { failure };
  if (invocation.exitCode !== 0) return { failure: result(target, stage, 'PR_LOOKUP_FAILED', {
    repository: repo,
    diagnostic: diagnostic('PR_VIEW_FAILED', 'The pull request could not be read.'),
  }) };
  const parsed = parseJson(invocation);
  const pr = normalizePr(parsed, repo);
  if (!pr || (requireMergeability
    && (!safeProviderString(pr.mergeable, 32) || !safeProviderString(pr.mergeStateStatus, 64)))) {
    return { failure: result(target, stage, 'PR_LOOKUP_FAILED', {
      repository: repo,
      diagnostic: diagnostic('PR_VIEW_MALFORMED', 'The pull request view returned invalid fields.'),
    }) };
  }
  if (pr.number !== prNumber || pr.headRepositoryOwner !== repo.owner || pr.headRefName !== target.storyBranch
    || pr.baseRefName !== target.integrationBranch) return { failure: result(target, stage, 'PR_LOOKUP_FAILED', {
    repository: repo,
    diagnostic: diagnostic('PR_IDENTITY_MISMATCH', 'The pull request view does not match the selected repository, head and base.'),
  }) };
  if (pr.headRefOid !== target.expectedHead) return { failure: result(target, stage, 'HEAD_MISMATCH', {
    repository: repo,
    pr: publicPr(pr),
    diagnostic: diagnostic('PR_HEAD_MISMATCH', 'The pull request head differs from expectedHead.'),
  }) };
  if (pr.state === 'MERGED') return allowMerged
    ? { pr }
    : { failure: result(target, stage, 'PR_MERGED', { repository: repo, pr: publicPr(pr) }) };
  if (pr.state !== 'OPEN') return { failure: result(target, stage, 'PR_CLOSED', { repository: repo, pr: publicPr(pr) }) };
  return { pr };
}

function unsettledMergeState(pr) {
  return pr.mergeable !== 'MERGEABLE' || pr.mergeStateStatus !== 'CLEAN';
}

function checks(target, repo, pr, run, timeoutMs) {
  if (pr.isDraft) return result(target, 'checks', 'PR_DRAFT', { repository: repo, pr: publicPr(pr) });
  const invocation = command(run, timeoutMs, 'gh', ['pr', 'checks', String(pr.number), '--repo', repo.slug,
    '--required', '--json', CHECK_FIELDS], target.root);
  const commandProblem = commandFailure(target, 'checks', 'gh', invocation, 'CHECKS_UNKNOWN', 'CHECKS_COMMAND_ERROR', 'Required checks could not be inspected.');
  if (commandProblem) return commandProblem;
  let normalizedChecks = [];
  let noRequiredChecks = false;
  if (invocation.stdout !== '') {
    const parsed = parseJson(invocation);
    if (!Array.isArray(parsed) || parsed.length > MAX_PROVIDER_ITEMS || parsed.some((item) => !record(item)
      || !['name', 'state', 'bucket', 'workflow'].every((key) => safeProviderString(item[key], 1000)))) {
      return result(target, 'checks', 'CHECKS_UNKNOWN', {
        repository: repo, pr: publicPr(pr), diagnostic: diagnostic('CHECKS_MALFORMED', 'Required checks returned invalid JSON.'),
      });
    }
    normalizedChecks = parsed.map((item) => ({
      name: item.name, state: item.state, bucket: item.bucket.toLowerCase(), workflow: item.workflow,
    }));
    if (invocation.exitCode !== 0) return result(target, 'checks', 'CHECKS_UNKNOWN', {
      repository: repo, pr: publicPr(pr), checks: normalizedChecks,
      diagnostic: diagnostic('CHECKS_EXIT_MISMATCH', 'Required checks returned JSON with a nonzero status.'),
    });
    if (normalizedChecks.some((item) => ['fail', 'cancel'].includes(item.bucket))) {
      return result(target, 'checks', 'CHECKS_FAILED', { repository: repo, pr: publicPr(pr), checks: normalizedChecks });
    }
    if (normalizedChecks.some((item) => item.bucket === 'pending')) {
      return result(target, 'checks', 'CHECKS_PENDING', { repository: repo, pr: publicPr(pr), checks: normalizedChecks });
    }
    if (normalizedChecks.some((item) => !['pass', 'skipping'].includes(item.bucket))) {
      return result(target, 'checks', 'CHECKS_UNKNOWN', {
        repository: repo, pr: publicPr(pr), checks: normalizedChecks,
        diagnostic: diagnostic('CHECKS_UNKNOWN_BUCKET', 'A required check has an unknown result bucket.'),
      });
    }
  } else if (invocation.exitCode === 0) {
    return result(target, 'checks', 'CHECKS_UNKNOWN', {
      repository: repo, pr: publicPr(pr),
      diagnostic: diagnostic('CHECKS_MALFORMED', 'Required checks returned no JSON.'),
    });
  } else {
    const stderr = trimOneLineEnding(invocation.stderr);
    if (invocation.exitCode !== 1 || invocation.stdout !== '' || !NO_CHECKS(target.storyBranch).has(stderr)) {
      return result(target, 'checks', 'CHECKS_UNKNOWN', {
        repository: repo, pr: publicPr(pr), diagnostic: diagnostic('CHECKS_LOOKUP_FAILED', 'Required checks could not be established.'),
      });
    }
    noRequiredChecks = true;
  }

  const fresh = view(target, repo, pr.number, run, timeoutMs);
  if (fresh.failure) return fresh.failure;
  if (fresh.pr.isDraft) return result(target, 'checks', 'PR_DRAFT', { repository: repo, pr: publicPr(fresh.pr) });
  if (unsettledMergeState(fresh.pr)) return result(target, 'checks', 'CHECKS_UNKNOWN', {
    repository: repo,
    pr: publicPr(fresh.pr),
    checks: normalizedChecks,
    diagnostic: diagnostic(noRequiredChecks ? 'NO_CHECKS_NOT_CLEAN' : 'MERGE_STATE_NOT_CLEAN',
      'The pull request is not in a clean mergeable state.'),
  });
  return result(target, 'checks', 'READY', {
    repository: repo,
    pr: publicPr(fresh.pr),
    checks: normalizedChecks,
    ...(noRequiredChecks ? { diagnostic: diagnostic('NO_REQUIRED_CHECKS_PROVEN', 'No required checks are configured and the pull request is clean.') } : {}),
  });
}

function withBodyFile(body, callback) {
  const temporaryBase = fs.realpathSync.native(path.resolve(os.tmpdir()));
  if (!path.isAbsolute(temporaryBase) || !fs.statSync(temporaryBase).isDirectory()) {
    throw new Error('Temporary file base must be an absolute directory');
  }
  const directory = fs.mkdtempSync(path.join(temporaryBase, 'deliver-remote-'));
  try {
    fs.chmodSync(directory, 0o700);
    const file = path.join(directory, 'body.md');
    const fd = fs.openSync(file, 'wx', 0o600);
    try {
      fs.fchmodSync(fd, 0o600);
      fs.writeFileSync(fd, body, 'utf8');
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
    return callback(file);
  }
  finally { fs.rmSync(directory, { recursive: true, force: true }); }
}

function publishOptions(options) {
  if (!record(options)) invalid('publish options must be an object');
  const unknown = Object.keys(options).filter((key) => !['title', 'body', 'createDraft', 'markReady'].includes(key));
  if (unknown.length) invalid(`unsupported publish fields: ${unknown.join(', ')}`);
  if (typeof options.createDraft !== 'boolean'
    || (options.markReady !== undefined && typeof options.markReady !== 'boolean')) invalid('publish draft options must be booleans');
  return {
    title: boundedLine(options.title, 'title'),
    body: boundedBody(options.body, 'body'),
    createDraft: options.createDraft,
    markReady: options.markReady ?? false,
  };
}

function mergeOptions(options) {
  if (!record(options)) invalid('merge options must be an object');
  const unknown = Object.keys(options).filter((key) => !['prNumber', 'method', 'subject', 'body'].includes(key));
  if (unknown.length) invalid(`unsupported merge fields: ${unknown.join(', ')}`);
  if (!Number.isSafeInteger(options.prNumber) || options.prNumber <= 0) invalid('prNumber must be a positive safe integer');
  if (!['merge', 'squash', 'rebase'].includes(options.method)) invalid('method must be merge, squash or rebase');
  return {
    prNumber: options.prNumber,
    method: options.method,
    subject: boundedLine(options.subject, 'subject'),
    body: boundedBody(options.body, 'body'),
  };
}

function reconcileOptions(options) {
  if (!record(options)) invalid('reconcile options must be an object');
  const unknown = Object.keys(options).filter((key) => key !== 'prNumber');
  if (unknown.length) invalid(`unsupported reconcile fields: ${unknown.join(', ')}`);
  if (!Number.isSafeInteger(options.prNumber) || options.prNumber <= 0) invalid('prNumber must be a positive safe integer');
  return { prNumber: options.prNumber };
}

function inspectRemoteBase(target, repo, run, timeoutMs) {
  const invocation = command(run, timeoutMs, 'git', ['ls-remote', '--refs', target.remote,
    `refs/heads/${target.integrationBranch}`], target.root);
  const problem = commandFailure(target, 'lookup', 'git', invocation, 'GIT_ERROR', 'REMOTE_BASE_ERROR', 'Git could not inspect the remote integration branch.');
  if (problem) return { failure: problem };
  const lines = trimOneLineEnding(invocation.stdout).split('\n').filter(Boolean);
  const match = lines.length === 1 ? /^([0-9a-f]{40}(?:[0-9a-f]{24})?)\t(refs\/heads\/.+)$/.exec(lines[0]) : null;
  if (invocation.exitCode !== 0 || !match || match[2] !== `refs/heads/${target.integrationBranch}`) {
    return { failure: result(target, 'lookup', 'GIT_ERROR', { repository: repo,
      diagnostic: diagnostic('REMOTE_BASE_UNPROVEN', 'The remote integration branch did not resolve to one full object ID.') }) };
  }
  return { oid: match[1] };
}

export function createGitHubRemoteAdapter({ run = runCommand, timeoutMs = 30_000 } = {}) {
  if (typeof run !== 'function') invalid('run must be a command runner');
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 300_000) invalid('timeoutMs is out of bounds');

  return Object.freeze({
    inspect(targetInput) {
      const prepared = preflight(targetInput, run, timeoutMs);
      if (prepared.failure) return prepared.failure;
      const base = inspectRemoteBase(prepared.target, prepared.repo, run, timeoutMs);
      if (base.failure) return base.failure;
      const found = lookup(prepared.target, prepared.repo, run, timeoutMs);
      if (found.failure) return { ...found.failure, remoteBase: base.oid };
      const viewed = view(prepared.target, prepared.repo, found.pr.number, run, timeoutMs);
      if (viewed.failure) return { ...viewed.failure, remoteBase: base.oid };
      return { ...checks(prepared.target, prepared.repo, viewed.pr, run, timeoutMs), remoteBase: base.oid };
    },

    publish(targetInput, optionsInput) {
      const options = publishOptions(optionsInput);
      const prepared = preflight(targetInput, run, timeoutMs);
      if (prepared.failure) return prepared.failure;
      const initial = lookup(prepared.target, prepared.repo, run, timeoutMs, { allowStaleHead: true });
      let existing = null;
      if (initial.failure?.state !== 'PR_ABSENT') {
        if (initial.failure) return initial.failure;
        existing = initial.pr;
      }

      const pushed = command(run, timeoutMs, 'git', ['push', '--porcelain', prepared.target.remote,
        `${prepared.target.expectedHead}:refs/heads/${prepared.target.storyBranch}`], prepared.target.root);
      const pushProblem = commandFailure(prepared.target, 'publish', 'git', pushed, 'PUSH_REJECTED', 'PUSH_COMMAND_ERROR', 'The exact branch push could not be completed.');
      if (pushProblem) return pushProblem;
      if (pushed.exitCode !== 0) return result(prepared.target, 'publish', 'PUSH_REJECTED', {
        repository: prepared.repo,
        diagnostic: diagnostic('PUSH_REJECTED', 'The remote rejected the exact branch update.'),
      });

      const writeArgs = existing
        ? ['pr', 'edit', String(existing.number), '--repo', prepared.repo.slug, '--title', options.title]
        : ['pr', 'create', '--repo', prepared.repo.slug, '--head', prepared.target.storyBranch,
          '--base', prepared.target.integrationBranch, '--title', options.title];
      let written;
      try {
        written = withBodyFile(options.body, (bodyFile) => command(run, timeoutMs, 'gh', [
          ...writeArgs, '--body-file', bodyFile, ...(!existing && options.createDraft ? ['--draft'] : []),
        ], prepared.target.root));
      } catch {
        return result(prepared.target, 'publish', 'PR_WRITE_FAILED', {
          repository: prepared.repo,
          diagnostic: diagnostic('PR_BODY_WRITE_FAILED', 'The bounded pull request body could not be prepared.'),
        });
      }
      const writeProblem = commandFailure(prepared.target, 'publish', 'gh', written, 'PR_WRITE_FAILED', 'PR_WRITE_ERROR', 'The pull request could not be created or updated.');
      if (writeProblem) return writeProblem;
      if (written.exitCode !== 0) return result(prepared.target, 'publish', 'PR_WRITE_FAILED', {
        repository: prepared.repo,
        diagnostic: diagnostic('PR_WRITE_FAILED', 'The pull request could not be created or updated.'),
      });

      let found = lookup(prepared.target, prepared.repo, run, timeoutMs);
      if (found.failure) return found.failure.state === 'PR_ABSENT'
        ? result(prepared.target, 'lookup', 'PR_LOOKUP_FAILED', {
          repository: prepared.repo,
          diagnostic: diagnostic('PR_NOT_VISIBLE_AFTER_WRITE', 'The pull request was not visible after publication.'),
        }) : found.failure;
      if (options.markReady && found.pr.isDraft) {
        const readied = command(run, timeoutMs, 'gh', ['pr', 'ready', String(found.pr.number), '--repo', prepared.repo.slug], prepared.target.root);
        const readyProblem = commandFailure(prepared.target, 'publish', 'gh', readied, 'PR_READY_FAILED', 'PR_READY_ERROR', 'The draft pull request could not be marked ready.');
        if (readyProblem) return readyProblem;
        if (readied.exitCode !== 0) return result(prepared.target, 'publish', 'PR_READY_FAILED', {
          repository: prepared.repo,
          pr: publicPr(found.pr),
          diagnostic: diagnostic('PR_READY_FAILED', 'The draft pull request could not be marked ready.'),
        });
        found = lookup(prepared.target, prepared.repo, run, timeoutMs);
        if (found.failure) return found.failure;
      }
      const viewed = view(prepared.target, prepared.repo, found.pr.number, run, timeoutMs);
      if (viewed.failure) return viewed.failure;
      if (options.markReady && viewed.pr.isDraft) return result(prepared.target, 'publish', 'PR_READY_FAILED', {
        repository: prepared.repo,
        pr: publicPr(viewed.pr),
        diagnostic: diagnostic('PR_STILL_DRAFT', 'The pull request remains draft after the ready request.'),
      });
      return result(prepared.target, 'publish', 'PUBLISHED', {
        repository: prepared.repo,
        pr: publicPr(viewed.pr),
      });
    },

    merge(targetInput, optionsInput) {
      const options = mergeOptions(optionsInput);
      const prepared = preflight(targetInput, run, timeoutMs);
      if (prepared.failure) return prepared.failure;
      const found = lookup(prepared.target, prepared.repo, run, timeoutMs);
      if (found.failure) return found.failure;
      if (found.pr.number !== options.prNumber) return result(prepared.target, 'lookup', 'PR_LOOKUP_FAILED', {
        repository: prepared.repo,
        pr: publicPr(found.pr),
        diagnostic: diagnostic('PR_NUMBER_MISMATCH', 'The supplied pull request number does not match the exact head and base.'),
      });
      const viewed = view(prepared.target, prepared.repo, options.prNumber, run, timeoutMs);
      if (viewed.failure) return viewed.failure;
      const readiness = checks(prepared.target, prepared.repo, viewed.pr, run, timeoutMs);
      if (readiness.state !== 'READY') return readiness;
      const beforeMerge = view(prepared.target, prepared.repo, options.prNumber, run, timeoutMs);
      if (beforeMerge.failure) return beforeMerge.failure;
      if (beforeMerge.pr.isDraft) return result(prepared.target, 'merge', 'PR_DRAFT', {
        repository: prepared.repo, pr: publicPr(beforeMerge.pr),
      });
      if (unsettledMergeState(beforeMerge.pr)) return result(prepared.target, 'merge', 'CHECKS_UNKNOWN', {
        repository: prepared.repo,
        pr: publicPr(beforeMerge.pr),
        diagnostic: diagnostic('PREMERGE_STATE_NOT_CLEAN', 'The pull request is no longer clean and mergeable.'),
      });

      let merged;
      try {
        merged = withBodyFile(options.body, (bodyFile) => command(run, timeoutMs, 'gh', [
          'pr', 'merge', String(options.prNumber), '--repo', prepared.repo.slug,
          '--match-head-commit', prepared.target.expectedHead, `--${options.method}`,
          '--subject', options.subject, '--body-file', bodyFile,
        ], prepared.target.root));
      } catch {
        return result(prepared.target, 'merge', 'MERGE_REJECTED', {
          repository: prepared.repo,
          diagnostic: diagnostic('MERGE_BODY_WRITE_FAILED', 'The bounded merge body could not be prepared.'),
        });
      }
      const mergeProblem = commandFailure(prepared.target, 'merge', 'gh', merged, 'MERGE_REJECTED', 'MERGE_COMMAND_ERROR', 'The pull request merge was rejected.');
      if (mergeProblem) return mergeProblem;
      if (merged.exitCode !== 0) return result(prepared.target, 'merge', 'MERGE_REJECTED', {
        repository: prepared.repo,
        diagnostic: diagnostic('MERGE_REJECTED', 'The pull request merge was rejected.'),
      });

      const after = view(prepared.target, prepared.repo, options.prNumber, run, timeoutMs, {
        allowMerged: true,
        stage: 'postmerge',
      });
      if (after.failure) {
        if (after.failure.state === 'HEAD_MISMATCH' || after.failure.state === 'PR_CLOSED') {
          return result(prepared.target, 'postmerge', 'MERGE_MISMATCH', {
            repository: prepared.repo,
            diagnostic: diagnostic('POSTMERGE_IDENTITY_MISMATCH', 'The post-merge pull request identity changed.'),
          });
        }
        return after.failure;
      }
      if (after.pr.state === 'OPEN') return result(prepared.target, 'postmerge', 'MERGE_PENDING', {
        repository: prepared.repo, pr: publicPr(after.pr),
        diagnostic: diagnostic('MERGE_NOT_FINAL', 'The provider accepted the merge request but has not merged the pull request.'),
      });
      const mergeOid = after.pr.mergeCommit?.oid;
      if (after.pr.state !== 'MERGED' || typeof mergeOid !== 'string' || !OID.test(mergeOid)) {
        return result(prepared.target, 'postmerge', 'MERGE_MISMATCH', {
          repository: prepared.repo, pr: publicPr(after.pr),
          diagnostic: diagnostic('MERGE_COMMIT_MISSING', 'The provider did not return a full merged commit object ID.'),
        });
      }
      const remoteBase = command(run, timeoutMs, 'git', ['ls-remote', '--refs', prepared.target.remote,
        `refs/heads/${prepared.target.integrationBranch}`], prepared.target.root);
      const baseProblem = commandFailure(prepared.target, 'postmerge', 'git', remoteBase, 'GIT_ERROR', 'REMOTE_BASE_ERROR', 'Git could not verify the remote integration branch.');
      if (baseProblem) return baseProblem;
      if (remoteBase.exitCode !== 0) return result(prepared.target, 'postmerge', 'GIT_ERROR', {
        repository: prepared.repo,
        diagnostic: diagnostic('REMOTE_BASE_FAILED', 'Git could not verify the remote integration branch.'),
      });
      const lines = trimOneLineEnding(remoteBase.stdout).split('\n').filter(Boolean);
      const match = lines.length === 1 ? /^([0-9a-f]{40}(?:[0-9a-f]{24})?)\t(refs\/heads\/.+)$/.exec(lines[0]) : null;
      if (!match || match[2] !== `refs/heads/${prepared.target.integrationBranch}` || match[1] !== mergeOid) {
        return result(prepared.target, 'postmerge', 'MERGE_MISMATCH', {
          repository: prepared.repo,
          mergeCommit: mergeOid,
          diagnostic: diagnostic('REMOTE_BASE_MISMATCH', 'The remote integration branch does not exactly match the merged commit.'),
        });
      }
      return result(prepared.target, 'postmerge', 'MERGED', {
        repository: prepared.repo,
        pr: publicPr(after.pr),
        mergeCommit: mergeOid,
        remoteBase: match[1],
      });
    },

    reconcileMerged(targetInput, optionsInput) {
      const options = reconcileOptions(optionsInput);
      const prepared = preflight(targetInput, run, timeoutMs);
      if (prepared.failure) return prepared.failure;
      const viewed = view(prepared.target, prepared.repo, options.prNumber, run, timeoutMs, {
        allowMerged: true,
        stage: 'postmerge',
        requireMergeability: false,
      });
      if (viewed.failure) {
        if (viewed.failure.diagnostic?.code === 'PR_VIEW_MALFORMED'
          || viewed.failure.state === 'PR_CLOSED' || viewed.failure.state === 'PR_MERGED') {
          return result(prepared.target, 'postmerge', 'UNKNOWN', {
            repository: prepared.repo,
            diagnostic: diagnostic('MERGE_PROOF_UNKNOWN', 'The pull request does not provide a complete merged result.'),
          });
        }
        return viewed.failure;
      }
      if (viewed.pr.state === 'OPEN') {
        return result(prepared.target, 'postmerge', 'MERGE_PENDING', {
          repository: prepared.repo,
          pr: publicPr(viewed.pr),
          diagnostic: diagnostic('MERGE_NOT_FINAL', 'The pull request has not reached a final merged state.'),
        });
      }
      const mergeOid = viewed.pr.mergeCommit?.oid;
      if (viewed.pr.state !== 'MERGED' || typeof mergeOid !== 'string' || !OID.test(mergeOid)) {
        return result(prepared.target, 'postmerge', 'UNKNOWN', {
          repository: prepared.repo,
          pr: publicPr(viewed.pr),
          diagnostic: diagnostic('MERGE_COMMIT_MISSING', 'The provider did not return a full merged commit object ID.'),
        });
      }
      const remoteBase = command(run, timeoutMs, 'git', ['ls-remote', '--refs', prepared.target.remote,
        `refs/heads/${prepared.target.integrationBranch}`], prepared.target.root);
      const baseProblem = commandFailure(prepared.target, 'postmerge', 'git', remoteBase, 'GIT_ERROR', 'REMOTE_BASE_ERROR', 'Git could not verify the remote integration branch.');
      if (baseProblem) return baseProblem;
      if (remoteBase.exitCode !== 0) return result(prepared.target, 'postmerge', 'GIT_ERROR', {
        repository: prepared.repo,
        diagnostic: diagnostic('REMOTE_BASE_FAILED', 'Git could not verify the remote integration branch.'),
      });
      const lines = trimOneLineEnding(remoteBase.stdout).split('\n').filter(Boolean);
      const match = lines.length === 1 ? /^([0-9a-f]{40}(?:[0-9a-f]{24})?)\t(refs\/heads\/.+)$/.exec(lines[0]) : null;
      if (!match || match[2] !== `refs/heads/${prepared.target.integrationBranch}`) {
        return result(prepared.target, 'postmerge', 'UNKNOWN', {
          repository: prepared.repo,
          pr: publicPr(viewed.pr),
          mergeCommit: mergeOid,
          diagnostic: diagnostic('REMOTE_BASE_UNKNOWN', 'The remote integration branch did not return one full exact ref.'),
        });
      }
      return result(prepared.target, 'postmerge', match[1] === mergeOid ? 'MERGED' : 'MERGED_BASE_ADVANCED', {
        repository: prepared.repo,
        pr: publicPr(viewed.pr),
        mergeCommit: mergeOid,
        remoteBase: match[1],
      });
    },
  });
}

import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export const STATE_VERSION = 1;

export class DeliverError extends Error {
  constructor(message, code = 70, details = undefined) {
    super(message);
    this.name = 'DeliverError';
    this.code = code;
    this.details = details;
  }
}

export const sha256 = (value) => createHash('sha256').update(value).digest('hex');

export function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

const REMOTE_HASH = /^[0-9a-f]{64}$/;
const REMOTE_OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const REMOTE_TOKEN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

const remoteRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const withoutRemoteIdentity = (value) => {
  const { identity: _identity, ...body } = value;
  return body;
};
const validRemoteIdentified = (value) => remoteRecord(value) && REMOTE_HASH.test(value.identity || '')
  && value.identity === sha256(canonical(withoutRemoteIdentity(value)));
const remoteInvalid = (message) => { throw new DeliverError(`invalid remote publication evidence: ${message}`, 66); };

// Provider-attempt identity covers immutable intent. Transitions and reciprocal
// disposition links are independently identified so later observations cannot
// invalidate an effect that names the original attempt.
export function remoteProviderAttemptIdentity(attempt) {
  return sha256(canonical({
    version: attempt.version,
    token: attempt.token,
    operation: attempt.operation,
    ordinal: attempt.ordinal,
    input: attempt.input,
    input_identity: attempt.input_identity,
    predecessor_record_hash: attempt.predecessor_record_hash,
    retry: attempt.retry,
    supersedes: attempt.supersedes,
  }));
}

export function remoteProviderAttemptObservation(attempt) {
  const observation = structuredClone(attempt?.input?.remote_observation);
  if (!remoteRecord(observation) || observation.version !== 'remote-provider-observation-v1') return null;
  const observed = attempt.transitions?.at(-1);
  if (observed?.state !== 'observed') return observation;
  const result = observed.result;
  if (Object.hasOwn(result, 'repository')) {
    if (!remoteRecord(result.repository)) return null;
    observation.repository_identity = sha256(canonical(result.repository));
  }
  if (Object.hasOwn(result, 'pr')) {
    if (!remoteRecord(result.pr) || !Number.isSafeInteger(result.pr.number) || result.pr.number <= 0
      || typeof result.pr.headRefName !== 'string' || !result.pr.headRefName
      || typeof result.pr.baseRefName !== 'string' || !result.pr.baseRefName
      || !REMOTE_OID.test(result.pr.headRefOid || '')) return null;
    observation.pr_number = result.pr.number;
    observation.story_branch = result.pr.headRefName;
    observation.integration_branch = result.pr.baseRefName;
    observation.observed_remote_head = result.pr.headRefOid;
  }
  if (Object.hasOwn(result, 'remoteBase')) {
    if (!REMOTE_OID.test(result.remoteBase || '')) return null;
    observation.observed_remote_base = result.remoteBase;
  }
  observation.result_identity = observed.result_identity;
  return observation;
}

function validateRemoteProviderSlot(slot, label) {
  if (!remoteRecord(slot) || slot.version !== 'remote-provider-slot-v1' || !Array.isArray(slot.attempts)
    || !(slot.active_token === null || REMOTE_TOKEN.test(slot.active_token || ''))
    || !(slot.effect === null || validRemoteIdentified(slot.effect))) remoteInvalid(`${label} provider slot`);
  const tokens = new Map();
  for (const attempt of slot.attempts) {
    if (!remoteRecord(attempt) || attempt.version !== 'remote-provider-attempt-v1'
      || !REMOTE_TOKEN.test(attempt.token || '') || tokens.has(attempt.token)
      || !Number.isSafeInteger(attempt.ordinal) || attempt.ordinal < 0
      || attempt.ordinal !== tokens.size || typeof attempt.operation !== 'string'
      || !REMOTE_HASH.test(attempt.input_identity || '')
      || attempt.input_identity !== sha256(canonical(attempt.input))
      || !REMOTE_HASH.test(attempt.predecessor_record_hash || '')
      || !Number.isSafeInteger(attempt.retry) || attempt.retry < 0 || attempt.retry > 2
      || !(attempt.supersedes === null || REMOTE_TOKEN.test(attempt.supersedes || ''))
      || !(attempt.superseded_by === null || REMOTE_TOKEN.test(attempt.superseded_by || ''))
      || !['active', 'superseded', 'proven'].includes(attempt.disposition)
      || !Array.isArray(attempt.transitions) || !attempt.transitions.length
      || attempt.identity !== remoteProviderAttemptIdentity(attempt)) remoteInvalid(`${label} provider attempt`);
    let previous = null;
    let previousTransition = null;
    for (const [transitionIndex, transition] of attempt.transitions.entries()) {
      if (!validRemoteIdentified(transition) || !['prepared', 'executing', 'observed'].includes(transition.state)
        || transition.previous !== previous || typeof transition.at !== 'string') remoteInvalid(`${label} provider transition`);
      if (transitionIndex === 0 && transition.state !== 'prepared') remoteInvalid(`${label} provider transition must begin prepared`);
      if (transitionIndex > 0) {
        const legal = previousTransition.state === 'prepared' ? transition.state === 'executing'
          : previousTransition.state === 'executing' && ['prepared', 'observed'].includes(transition.state);
        if (!legal) remoteInvalid(`${label} provider transition order`);
      }
      if (transition.state === 'executing' && (!remoteRecord(transition.invocation)
        || !REMOTE_TOKEN.test(transition.invocation.token || '')
        || !Number.isSafeInteger(transition.invocation.pid) || transition.invocation.pid <= 0
        || !REMOTE_TOKEN.test(transition.invocation.process_instance || '')
        || transition.invocation.operation !== attempt.operation
        || transition.invocation.input_identity !== attempt.input_identity)) remoteInvalid(`${label} executing transition`);
      if (transition.state === 'observed' && (!REMOTE_HASH.test(transition.result_identity || '')
        || transition.result_identity !== sha256(canonical(transition.result)))) remoteInvalid(`${label} observed transition`);
      if (transition.state === 'observed' && transition.invocation_token !== previousTransition?.invocation?.token) {
        remoteInvalid(`${label} observed invocation binding`);
      }
      if (transition.state === 'prepared' && transitionIndex > 0) {
        if (!validRemoteIdentified(transition.replay)
          || transition.replay.version !== 'remote-provider-replay-proof-v1'
          || transition.replay.invocation_token !== previousTransition?.invocation?.token
          || transition.replay.absence_result?.state !== 'PR_ABSENT'
          || transition.replay.absence_identity !== sha256(canonical(transition.replay.absence_result))) {
          remoteInvalid(`${label} replay proof`);
        }
      } else if (transition.replay) remoteInvalid(`${label} unexpected replay proof`);
      if (transition.supersession && !validRemoteIdentified(transition.supersession)) remoteInvalid(`${label} supersession proof`);
      previous = transition.identity;
      previousTransition = transition;
    }
    tokens.set(attempt.token, attempt);
  }
  if (slot.active_token !== null) {
    const active = tokens.get(slot.active_token);
    if (!active || active !== slot.attempts.at(-1) || active.disposition !== 'active'
      || !['prepared', 'executing'].includes(active.transitions.at(-1).state)) remoteInvalid(`${label} active token`);
  }
  for (const attempt of slot.attempts) {
    const terminal = attempt.transitions.at(-1);
    if (['prepared', 'executing'].includes(terminal.state)
      && (slot.active_token !== attempt.token || attempt.disposition !== 'active')) remoteInvalid(`${label} unfinished attempt state`);
    if (terminal.state === 'observed' && slot.active_token === attempt.token) remoteInvalid(`${label} observed active token`);
    if (attempt.disposition === 'proven' && terminal.state !== 'observed') remoteInvalid(`${label} proven disposition`);
    if (attempt.disposition === 'superseded' && (terminal.state !== 'observed' || attempt.superseded_by === null)) {
      remoteInvalid(`${label} superseded disposition`);
    }
  }
  for (const attempt of slot.attempts) {
    if (attempt.superseded_by !== null) {
      const successor = tokens.get(attempt.superseded_by);
      const proof = successor?.transitions?.[0]?.supersession;
      const priorObservation = remoteProviderAttemptObservation(attempt);
      const currentObservation = successor?.input?.remote_observation;
      const changedFields = ['observed_remote_head', 'observed_remote_base']
        .filter((field) => priorObservation?.[field] !== currentObservation?.[field]);
      if (attempt.disposition !== 'superseded' || successor?.supersedes !== attempt.token
        || !validRemoteIdentified(proof) || proof.predecessor_token !== attempt.token
        || proof.predecessor_attempt_identity !== attempt.identity
        || proof.successor_token !== successor.token
        || !validRemoteObservation(priorObservation) || !validRemoteObservation(currentObservation)
        || proof.prior_observation_identity !== sha256(canonical(priorObservation))
        || proof.current_observation_identity !== sha256(canonical(currentObservation))
        || canonical(proof.changed_fields) !== canonical(changedFields)
        || changedFields.length === 0
        || !(proof.predecessor_effect === null
          ? proof.predecessor_effect_identity === null
          : validRemoteIdentified(proof.predecessor_effect)
            && proof.predecessor_effect.identity === proof.predecessor_effect_identity)) {
        remoteInvalid(`${label} reciprocal supersession`);
      }
      if (proof.predecessor_effect) {
        const priorObserved = attempt.transitions.find((transition) => transition.state === 'observed'
          && transition.result_identity === proof.predecessor_effect.result_identity);
        if (proof.predecessor_effect.attempt_identity !== attempt.identity || !priorObserved) {
          remoteInvalid(`${label} predecessor effect history`);
        }
      }
    }
    if (attempt.supersedes !== null) {
      const predecessor = tokens.get(attempt.supersedes);
      if (!predecessor || predecessor.superseded_by !== attempt.token) remoteInvalid(`${label} predecessor link`);
    }
  }
  if (slot.effect) {
    const attempt = slot.attempts.find((item) => item.identity === slot.effect.attempt_identity);
    const observed = attempt?.transitions?.find((item) => item.state === 'observed'
      && item.result_identity === slot.effect.result_identity);
    if (!attempt || !observed || !['proven', 'superseded'].includes(attempt.disposition)) remoteInvalid(`${label} effect binding`);
  }
  for (const attempt of slot.attempts) {
    if (attempt.disposition === 'proven' && slot.effect?.attempt_identity !== attempt.identity) {
      remoteInvalid(`${label} proven attempt lacks current effect`);
    }
    const effectState = ['PUBLISHED', 'READY', 'PR_DRAFT', 'CHECKS_PENDING', 'CHECKS_FAILED',
      'MERGED', 'MERGED_BASE_ADVANCED'].includes(attempt.transitions.at(-1).result?.state);
    if (attempt.disposition === 'active' && attempt.transitions.at(-1).state === 'observed'
      && (slot.effect?.attempt_identity === attempt.identity || effectState)) {
      remoteInvalid(`${label} unresolved attempt has effect`);
    }
  }
}

function requireRemoteIdentified(value, label) {
  if (!validRemoteIdentified(value)) remoteInvalid(`${label} identity`);
  return value;
}

function remoteEffectObservation(slot, label) {
  if (!slot?.effect) return null;
  const attempt = slot.attempts.find((item) => item.identity === slot.effect.attempt_identity);
  const observed = attempt?.transitions?.find((item) => item.state === 'observed'
    && item.result_identity === slot.effect.result_identity);
  if (!attempt || !observed) remoteInvalid(`${label} effect observation`);
  return { attempt, observed };
}

function validRemoteObservation(value) {
  return remoteRecord(value) && value.version === 'remote-provider-observation-v1'
    && (value.repository_identity === null || REMOTE_HASH.test(value.repository_identity || ''))
    && (value.pr_number === null || Number.isSafeInteger(value.pr_number) && value.pr_number > 0)
    && typeof value.story_branch === 'string' && value.story_branch.length > 0
    && typeof value.integration_branch === 'string' && value.integration_branch.length > 0
    && (value.observed_remote_head === null || REMOTE_OID.test(value.observed_remote_head || ''))
    && (value.observed_remote_base === null || REMOTE_OID.test(value.observed_remote_base || ''))
    && REMOTE_HASH.test(value.result_identity || '');
}

function validateRemoteEffectTarget(slot, expected, label, states) {
  const effect = remoteEffectObservation(slot, label);
  if (!effect) remoteInvalid(`${label} effect is missing`);
  const target = effect.attempt.input?.target;
  for (const [field, expectedValue] of Object.entries(expected)) {
    if (target?.[field] !== expectedValue) remoteInvalid(`${label} target ${field}`);
  }
  if (effect.observed.result?.expectedHead !== expected.expectedHead
    || !states.includes(effect.observed.result?.state)) remoteInvalid(`${label} provider result`);
  return effect;
}

function validateRemoteWrite(write, label) {
  if (!remoteRecord(write) || typeof write.path !== 'string' || !write.path
    || typeof write.after !== 'string' || !REMOTE_HASH.test(write.hash || '')
    || write.hash !== sha256(write.after)
    || !['100644', '100755'].includes(write.mode || '')) remoteInvalid(`${label} write`);
}

/**
 * Validate the identified, cross-bound remote publication envelope without
 * consulting a checkout. Callers separately prove live Git objects and roots.
 * Partial lifecycle states are accepted; requireTerminal demands the complete
 * source/evidence/closure-or-repair/completion chain used for admission.
 */
export function validateRemotePublicationRecord(value, { requireTerminal = false } = {}) {
  const remote = value?.remote;
  if (remote === undefined || remote === null) {
    if (requireTerminal) remoteInvalid('terminal envelope is missing');
    return value;
  }
  if (!remoteRecord(remote) || remote.version !== 'remote-publication-v1' || !remoteRecord(remote.source)
    || !remoteRecord(remote.handoff_repair) || !Array.isArray(remote.handoff_repair.attempts)
    || !Number.isSafeInteger(remote.handoff_repair.publication_retry)
